import{f as e,o as a,c as d,a4 as o}from"./chunks/framework.6QvN0vQS.js";const m=JSON.parse('{"title":"00 — Especificación Maestra de Alcance: CoopApps","description":"","frontmatter":{},"headers":[],"relativePath":"especificacion/00-ESPECIFICACION-MAESTRA.md","filePath":"especificacion/00-ESPECIFICACION-MAESTRA.md","lastUpdated":null}'),r={name:"especificacion/00-ESPECIFICACION-MAESTRA.md"};function n(i,t,s,c,l,p){return a(),d("div",null,[...t[0]||(t[0]=[o(`<h1 id="_00-—-especificacion-maestra-de-alcance-coopapps" tabindex="-1">00 — Especificación Maestra de Alcance: CoopApps <a class="header-anchor" href="#_00-—-especificacion-maestra-de-alcance-coopapps" aria-label="Permalink to &quot;00 — Especificación Maestra de Alcance: CoopApps&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Versión</td><td>1.0 (borrador consolidado)</td></tr><tr><td>Fecha</td><td>04-11-2026</td></tr><tr><td>Estado</td><td>Especificación consolidada al 10-11-2026; adaptación de stack y export GoodApps al 19-11-2026 (DEC-110–119; ver <code>06-impacto-adaptacion-stack-goodapps.md</code>). 31 anexos completos (M01–M19 y T01–T12), matriz (<code>04</code>), huecos (<code>05</code>), ER físico en elaboración (<code>07</code>)</td></tr><tr><td>Alcance</td><td>Sistema SaaS multitenant integral para cooperativas de servicios (ERP + CRM + autogestión + plataforma + cobranza + pasarelas + impuestos + APIs) que reemplaza a ProCoop</td></tr><tr><td>Uso</td><td>Fuente <strong>única y suficiente</strong> del alcance funcional y de las decisiones. La implementación con GoodApps usa el stack de §5 y el checklist de <code>06-impacto-adaptacion-stack-goodapps.md</code>. Olas y <strong>174 prompts</strong> en <code>03-plan-de-olas-y-prompts.md</code>; norma técnica de build en <code>03-norma-ejecucion-goodapps.md</code> (DEC-118)</td></tr></tbody></table><blockquote><p><strong>Regla de uso.</strong> Este documento es el índice rector. Define el concepto, las decisiones, la arquitectura, la tecnología, los roles, las aplicaciones, el mapa del sitio, los layouts, las convenciones y las olas de <strong>contenido</strong>. El detalle de cada módulo está en <code>anexos/</code>. Ante cualquier conflicto entre un anexo y este documento, <strong>prevalece este documento</strong> (sección 3); ante conflicto entre anexos, prevalece el anexo <strong>dueño del dato</strong> (sección 12 y <code>T05</code>). Para stack, nube, UI y entrega a GoodApps, prevalecen <strong>DEC-110–119</strong> y <code>06</code>.</p></blockquote><h2 id="indice" tabindex="-1">Índice <a class="header-anchor" href="#indice" aria-label="Permalink to &quot;Índice&quot;">​</a></h2><ol><li>Visión y concepto del producto</li><li>Fuentes consolidadas y jerarquía de prevalencia</li><li>Decisiones rectoras (DEC)</li><li>Alcance funcional: soluciones, servicios y módulos</li><li>Arquitectura y stack tecnológico 5b. <a href="./06-impacto-adaptacion-stack-goodapps">Adaptación GoodApps e impacto</a></li><li>Multitenancy y plataforma SaaS</li><li>Actores, roles y modelo de permisos</li><li>Aplicaciones y espacios de trabajo</li><li>Mapa del sitio (resumen)</li><li>MainLayouts</li><li>Design system, marca por tenant y diccionario 11b. <a href="./GUIA-UI-UX-DESARROLLO">Guía UI/UX para desarrollo</a> (documento exclusivo; detalle normativo en T03) 11c. <a href="./08-identidad-marca-coopapps">Identidad visual CoopApps (producto)</a> (DEC-119; assets en <code>docs/brand/coopapps/</code>)</li><li>Índice de módulos y dueños de datos</li><li>Convenciones transversales de desarrollo</li><li>Requisitos no funcionales (resumen)</li><li>Plan de olas (resumen)</li><li>Cómo usar esta especificación con GoodApps</li><li>Registro global de contraposiciones resueltas</li><li>Preguntas abiertas</li><li>Trazabilidad global de fuentes</li><li>Glosario general</li></ol><hr><h2 id="_1-vision-y-concepto-del-producto" tabindex="-1">1. Visión y concepto del producto <a class="header-anchor" href="#_1-vision-y-concepto-del-producto" aria-label="Permalink to &quot;1. Visión y concepto del producto&quot;">​</a></h2><h3 id="_1-1-problema" tabindex="-1">1.1 Problema <a class="header-anchor" href="#_1-1-problema" aria-label="Permalink to &quot;1.1 Problema&quot;">​</a></h3><p>Las cooperativas de servicios públicos argentinas (electricidad, agua, gas, Internet/TIC, telefonía, TV, sepelio, salud, vivienda y otros servicios sociales) operan con sistemas de escritorio instalados localmente, con una base de datos por cooperativa, parámetros numéricos sin semántica (ProCoop tiene <strong>1.536 parámetros</strong> en una tabla clave/valor), seguridad débil (contraseñas reversibles, usuario SQL compartido, secretos en el código), integraciones frágiles y nula experiencia digital para el socio.</p><h3 id="_1-2-propuesta" tabindex="-1">1.2 Propuesta <a class="header-anchor" href="#_1-2-propuesta" aria-label="Permalink to &quot;1.2 Propuesta&quot;">​</a></h3><p><strong>CoopApps</strong> es la plataforma SaaS multitenant, web y PWA, que cubre la operación integral de la cooperativa. Marca comercial elegida según el informe de naming del equipo (noviembre 2026): nombre corto <strong>CoopApps</strong> (pronunciación rioplatense: <em>Coop-apps</em>), bajada de trabajo <strong>«Gestión inteligente para cooperativas»</strong>, desarrollo y operación del servicio por <strong>GoodApps</strong> (empresa prestadora; contratos, encargos de datos personales y relación comercial SaaS).</p><ul><li><strong>ERP</strong>: personas y cuentas, catálogo de servicios, medición, tarifas, facturación multiservicio, fiscal, cuenta corriente y cobranza, mora y financiación, compras, stock, tesorería, contabilidad, sueldos, institucional y servicios sociales.</li><li><strong>CRM</strong>: solicitudes, reclamos, tickets, mesa de entradas, turnero, canales, bot e IA, técnica y campo.</li><li><strong>Landing y autogestión</strong>: sitio público con marca de la cooperativa, registro, portal y app del socio, pago online, comunidad editorial.</li><li><strong>Plataforma</strong>: alta y ciclo de vida de cooperativas, licencias por módulo, soporte auditado, ambientes, salud.</li><li><strong>Cobranza y pasarelas</strong>: cajas, entes recaudadores, débitos, pasarelas de pago, QR y conciliación.</li><li><strong>Liquidación de impuestos</strong>: ARCA, IVA, IIBB, percepciones, retenciones, tasas de terceros y regímenes informativos.</li><li><strong>APIs</strong>: API pública para terceros, webhooks y BI.</li></ul><p>Es el mapa de las 8 soluciones de BASE §105. El concepto visual y técnico es el de <strong>Connectia</strong> (CNX): admin web oscuro y denso para el personal, PWA con piel propia y branding runtime para socios y empleados de campo, y comunidad tipo muro editorial.</p><h3 id="_1-3-principios-de-producto" tabindex="-1">1.3 Principios de producto <a class="header-anchor" href="#_1-3-principios-de-producto" aria-label="Permalink to &quot;1.3 Principios de producto&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Principio</th><th>Origen</th></tr></thead><tbody><tr><td>P1</td><td>Una sola plataforma para todas las cooperativas y todos sus servicios; cada cooperativa habilita solo lo que contrata y configura.</td><td>BASE §2, §42, §66</td></tr><tr><td>P2</td><td><strong>Configuración, no programación</strong>: servicios, tarifas, conceptos, impuestos, textos y flujos se parametrizan por tenant con vigencias y versionado.</td><td>BASE §39, §81, §84; AGR-009/010</td></tr><tr><td>P3</td><td><strong>Diccionario de términos desde el inicio</strong>: ninguna etiqueta fija; cada tenant adapta su vocabulario (socio/usuario/asociado, suministro/conexión).</td><td>BASE §65</td></tr><tr><td>P4</td><td><strong>Factura multiservicio y separada</strong> como modos de primera clase.</td><td>BASE §103 (prevalece)</td></tr><tr><td>P5</td><td>Trazabilidad total: auditoría inmutable; los documentos económicos nunca se borran, se anulan o revierten.</td><td>BASE §29; AGR-003</td></tr><tr><td>P6</td><td>IA asistente que <strong>propone</strong> y no ejecuta sin confirmación, con permisos y auditoría.</td><td>BASE §102; AGR-030; CNX</td></tr><tr><td>P7</td><td>Experiencia del socio primero: autogestión en celular, una tarea principal por pantalla.</td><td>BASE §25, §102.5.6</td></tr><tr><td>P8</td><td>Seguridad por diseño: aislamiento de tenant verificable, secretos en bóveda, 2FA, mínimo privilegio.</td><td>BASE §60, §97; CNX §10</td></tr><tr><td>P9</td><td>Todo lo que hace ProCoop está en alcance, mejorado; las deudas técnicas de ProCoop se reemplazan y no se replican.</td><td>DEC-007</td></tr></tbody></table><h3 id="_1-4-piloto-de-referencia-dec-005" tabindex="-1">1.4 Piloto de referencia (DEC-005) <a class="header-anchor" href="#_1-4-piloto-de-referencia-dec-005" aria-label="Permalink to &quot;1.4 Piloto de referencia (DEC-005)&quot;">​</a></h3><p>El primer flujo completo de punta a punta es el del servicio <strong>Internet</strong>:</p><ol><li>Contratación.</li><li>Factibilidad.</li><li>Visita e instalación.</li><li>Equipo en comodato.</li><li>Activación y aprovisionamiento.</li><li>Facturación.</li><li>Pago.</li><li>Reclamo.</li><li>Mora y suspensión.</li><li>Baja.</li></ol><p>Las olas O2 a O6 lo cierran. Los servicios medidos (electricidad, agua, gas) llegan en O7.</p><p>La <strong>cooperativa piloto</strong> (comercial y de migración) es <strong>Laguna Larga</strong> (<code>LAG</code>) (DEC-088, que reemplaza a DEC-081; antes &quot;todavía no está definida&quot;). La especificación la sigue nombrando &quot;cooperativa piloto&quot;. Su base de ProCoop es también la <strong>base relevada de referencia</strong>: sus configuraciones y formatos se usan para el mapeo, las pruebas de paralelo y los <code>[VERIFICAR]</code>. Como opera servicios medidos (electricidad, gas y prepago), su primera migración real ocurre después de O7 (PA-MIG-17) y el corte avanza por etapas hasta O11 (DEC-068).</p><hr><h2 id="_2-fuentes-consolidadas-y-jerarquia-de-prevalencia" tabindex="-1">2. Fuentes consolidadas y jerarquía de prevalencia <a class="header-anchor" href="#_2-fuentes-consolidadas-y-jerarquia-de-prevalencia" aria-label="Permalink to &quot;2. Fuentes consolidadas y jerarquía de prevalencia&quot;">​</a></h2><h3 id="_2-1-fuentes" tabindex="-1">2.1 Fuentes <a class="header-anchor" href="#_2-1-fuentes" aria-label="Permalink to &quot;2.1 Fuentes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Código</th><th>Fuente</th><th>Contenido</th><th>Rol en esta especificación</th></tr></thead><tbody><tr><td>BASE</td><td><code>docs/base-funcional/PROCOOP_RELEVAMIENTO_Y_BASE_FUNCIONAL.md</code> v0.17</td><td>Secciones §1–§107: requisitos informados por el solicitante, propuestas validadas, casos de uso, mercado (§99), MER-001..020 (§100), complemento integrado (§102), factura multiservicio FAC-005..012 (§103), sueldos SUE-001..014 (§104), mapa de soluciones (§105), pendientes (§106), mensajes P-001..P-020</td><td><strong>Esqueleto rector</strong></td></tr><tr><td>AGR</td><td><code>docs/base-funcional/PROCOOP_COMPLEMENTO_ANALISIS_FUNCIONAL_Y_DISENO.md</code></td><td>AGR-001..036 (36 fichas), escenarios ESC-01..05, etapas de trabajo A–G</td><td>Complemento de diseño: bordes, estados, invariantes</td></tr><tr><td>CNX</td><td><code>referencia-connectia/connectia-referencia-para-goodapps.md</code></td><td>Stack, estructura, multitenant, licencias, auth, design system PWA y admin, muro, novedades, encuestas, audiencia, deudas de seguridad</td><td><strong>Formato técnico y UI/UX</strong></td></tr><tr><td>DFA</td><td><code>procoop-relevamiento/definicion-funcional-alcance.md</code></td><td>29 módulos de ProCoop con pantallas, procesos, modelo y prioridades A/B/C</td><td>Benchmark funcional</td></tr><tr><td>FIC</td><td><code>procoop-relevamiento/integraciones-fichas.md</code></td><td>23 secciones de integraciones</td><td>Benchmark de integraciones</td></tr><tr><td>RN-01..13</td><td><code>procoop-relevamiento/reglas-negocio/</code></td><td>Reglas extraídas del código (cálculo de factura, facturación masiva, mora, cobranzas, técnica, ERP administrativo, parámetros, integraciones, pasarelas…)</td><td>Benchmark de reglas</td></tr><tr><td>CAT</td><td><code>procoop-relevamiento/binarios/Procoop-catalogo-tablas.md</code></td><td>659 tablas en 31 secciones</td><td>Modelo legacy testigo</td></tr><tr><td>INV</td><td><code>procoop-relevamiento/binarios/inventarios/*.md</code></td><td>Formularios y métodos por módulo</td><td>Verificación de cobertura de pantallas</td></tr><tr><td>REL</td><td><code>procoop-relevamiento/README.md</code></td><td>Menú completo (9 pestañas), fichas, comprobantes de la DEMO</td><td>Verificación de cobertura de funciones</td></tr></tbody></table><h3 id="_2-2-jerarquia-de-prevalencia" tabindex="-1">2.2 Jerarquía de prevalencia <a class="header-anchor" href="#_2-2-jerarquia-de-prevalencia" aria-label="Permalink to &quot;2.2 Jerarquía de prevalencia&quot;">​</a></h3><ol><li><strong>DEC-xxx</strong> (sección 3): decisiones del solicitante.</li><li><strong>BASE</strong> en su redacción más reciente. Las secciones que declaran &quot;prevalece&quot; sustituyen a las anteriores: §103 sobre las exclusiones previas de la factura multiservicio y §104 sobre §28.</li><li><strong>AGR</strong>: se adopta salvo contradicción con 1 o 2.</li><li><strong>CNX</strong>: para lo técnico, la UI/UX, el layout, los componentes, los permisos y la comunidad.</li><li><strong>Benchmark ProCoop</strong> (DFA, FIC, RN, CAT, INV, REL): todo entra en alcance (DEC-007) salvo contradicción con 1–4 o que sea deuda técnica o de seguridad; en ese caso se registra como <code>Reemplazado por</code>.</li></ol><p>Cada contraposición se documenta con un ID <code>CTR-</code> en el anexo correspondiente y las globales en la sección 17.</p><h3 id="_2-3-revisiones-externas" tabindex="-1">2.3 Revisiones externas <a class="header-anchor" href="#_2-3-revisiones-externas" aria-label="Permalink to &quot;2.3 Revisiones externas&quot;">​</a></h3><p>Documentos contrastados con esta especificación que <strong>no son fuente</strong>: no entran en la tabla 2.1 ni en la jerarquía 2.2, y lo que aportan solo rige a través de una DEC.</p><table tabindex="0"><thead><tr><th>Documento</th><th>Estado</th><th>Efecto</th></tr></thead><tbody><tr><td><code>NucleoTransversal-Modelo</code> (documento externo; contraste en <code>docs/revision-externa/NucleoTransversal-contraste.md</code> y rechazos en <code>docs/revision-externa/NucleoTransversal-rechazados.md</code>)</td><td>Contrastado el 10-11-2026; no es fuente</td><td>Sus aportes aceptados entraron por DEC-093 a DEC-104 (aportes A1 a A11 y correcciones internas); la revisión de los rechazos dio DEC-105 a DEC-108. Los anexos citan la DEC, no el documento. Lo demás sigue rechazado con su motivo</td></tr><tr><td>GestionApps (sistema base mencionado por el documento externo)</td><td>No es fuente hoy (DEC-108)</td><td>No forma parte del diseño ni de la especificación porque no hay información disponible; podría analizarse en el futuro con el mismo criterio de contraste y, si aporta, incorporarse como fuente de referencia con su lugar en la jerarquía 2.2</td></tr></tbody></table><hr><h2 id="_3-decisiones-rectoras-dec" tabindex="-1">3. Decisiones rectoras (DEC) <a class="header-anchor" href="#_3-decisiones-rectoras-dec" aria-label="Permalink to &quot;3. Decisiones rectoras (DEC)&quot;">​</a></h2><p>Decisiones tomadas por el solicitante el 04-11-2026. Prevalecen sobre cualquier fuente.</p><table tabindex="0"><thead><tr><th>ID</th><th>Tema</th><th>Decisión</th><th>Consecuencias principales</th></tr></thead><tbody><tr><td>DEC-001</td><td>Stack</td><td>Connectia tal cual: <strong>Node.js 20 ESM + Express + MongoDB 7</strong> (replica set, transacciones multi-documento) <strong>+ Mongoose 8 + Vue 3.5 + Vite + Pinia + Vue Router + Tailwind</strong>, con las mejoras [MEJORAR] de CNX</td><td>Reemplaza las alternativas .NET/Azure/SQL Server de DFA. Agrega Zod, BullMQ+Redis, almacenamiento de objetos privado con URL firmadas, rate limiting, <code>DataTable</code> y <code>ExcelImportWizard</code> genéricos, motor único de audiencias y bóveda de credenciales por tenant.</td></tr><tr><td>DEC-002</td><td>Multitenancy</td><td><strong>Base de datos única compartida</strong> con <code>tenantId</code> en todo documento</td><td>Índices compuestos que empiezan por <code>tenantId</code>; tenant tomado del token; plugin Mongoose que impide consultas sin tenant; tenant especial <code>PLATFORM</code>. Reemplaza &quot;una base por cooperativa&quot; de ProCoop/DFA.</td></tr><tr><td>DEC-003</td><td>Arquitectura</td><td><strong>Monolito modular</strong> + outbox de eventos + workers BullMQ</td><td>Un backend con módulos de dominio con fronteras estrictas; cada módulo es dueño de sus colecciones; la comunicación entre módulos es por servicio público o por evento.</td></tr><tr><td>DEC-004</td><td>Despliegue</td><td><strong>Docker agnóstico de nube</strong>; AWS como referencia</td><td>Contenedores para API, workers, admin, PWA y landing; Mongo gestionado o replica set; Redis; almacenamiento S3-compatible.</td></tr><tr><td>DEC-005</td><td>Piloto</td><td><strong>Internet</strong></td><td>Las olas O2–O6 se orientan a cerrar Internet de punta a punta.</td></tr><tr><td>DEC-006</td><td>Planificación</td><td><strong>Olas sin fechas</strong></td><td>Las fechas de DFA quedan sin efecto; solo hay orden y dependencias.</td></tr><tr><td>DEC-007</td><td>Alcance</td><td><strong>Todo lo que hace ProCoop</strong></td><td>Incluye telefonía y tasación de CDR, TV, vivienda, salud/ambulancias/sepelio, fabricación, flota/GPS, turnero y agente de hardware; las prioridades C de DFA pasan a olas tardías, no se excluyen.</td></tr><tr><td>DEC-008</td><td>Comunidad</td><td><strong>Muro editorial</strong> con reacciones y comentarios moderados (IA + humano)</td><td>Los socios no publican posteos propios; la moderación es habilitable por tenant y por publicación.</td></tr><tr><td>DEC-009</td><td>Contabilidad</td><td><strong>Núcleo temprano</strong> (O5) y contabilidad completa en O8</td><td>El motor de asientos automáticos existe desde que hay eventos económicos.</td></tr><tr><td>DEC-010</td><td>Entregable</td><td>Maestro + anexos + plan de olas con prompts + registro de decisiones y preguntas</td><td>Estructura de <code>docs/especificacion/</code>.</td></tr></tbody></table><h3 id="_3-0-stack-de-implementacion-vigente-goodapps-19-11-2026" tabindex="-1">3.0 Stack de implementación vigente (GoodApps, 19-11-2026) <a class="header-anchor" href="#_3-0-stack-de-implementacion-vigente-goodapps-19-11-2026" aria-label="Permalink to &quot;3.0 Stack de implementación vigente (GoodApps, 19-11-2026)&quot;">​</a></h3><p>Las filas <strong>DEC-001</strong> a <strong>DEC-004</strong> registran el acuerdo del <strong>04-11-2026</strong> (patrón Connectia). Para <strong>construcción y export</strong> prevalecen <strong>DEC-110</strong> a <strong>DEC-113</strong>, <strong>DEC-117</strong> y <strong>DEC-118</strong>, detalladas en §5, <code>06-impacto-adaptacion-stack-goodapps.md</code> y <code>01</code> (DEC-111 reemplaza el stack de DEC-001; DEC-110 concreta multitenancy en Azure SQL; DEC-112 reemplaza el despliegue de DEC-004; DEC-118: olas en <code>03</code>; stack de build en <code>03-norma-ejecucion-goodapps.md</code>). El funcional (DEC-003 monolito modular, DEC-007 alcance, etc.) <strong>no cambia</strong>.</p><table tabindex="0"><thead><tr><th>DEC histórica</th><th>Tema</th><th>Reemplazo / vigente en implementación</th></tr></thead><tbody><tr><td>DEC-001</td><td>Stack Node + Mongo + Vue</td><td><strong>DEC-111</strong> (.NET 10 + Azure SQL + React 19 + EF Core)</td></tr><tr><td>DEC-002 (parte física)</td><td><code>tenantId</code> en documento, plugin Mongoose</td><td><strong>DEC-110</strong> (<code>TenantId</code> en tablas, filtros EF, índices compuestos) — semántica multitenant intacta</td></tr><tr><td>DEC-004</td><td>Docker agnóstico / AWS referencia</td><td><strong>DEC-112</strong> (Microsoft Azure)</td></tr><tr><td>DEC-001 (colas)</td><td>BullMQ + Redis</td><td><strong>Azure Queue Storage</strong> + workers .NET; Redis en Azure donde aplique (§5)</td></tr></tbody></table><p>Las respuestas a las preguntas abiertas se registran como <strong>DEC-011</strong> en adelante en <code>01-registro-decisiones.md</code> y se resumen en 3.1.</p><h3 id="_3-1-decisiones-sobre-preguntas-abiertas-dec-011-a-dec-108" tabindex="-1">3.1 Decisiones sobre preguntas abiertas (DEC-011 a DEC-108) <a class="header-anchor" href="#_3-1-decisiones-sobre-preguntas-abiertas-dec-011-a-dec-108" aria-label="Permalink to &quot;3.1 Decisiones sobre preguntas abiertas (DEC-011 a DEC-108)&quot;">​</a></h3><p>Resumen del registro <code>01-registro-decisiones.md</code>, que es la fuente con fecha y fundamento. Las preguntas no consultadas adoptan su opción recomendada (DEC-047 y DEC-072). Prevalecen sobre cualquier anexo.</p><table tabindex="0"><thead><tr><th>ID</th><th>Tema</th><th>Decisión</th><th>Anexos afectados</th></tr></thead><tbody><tr><td>DEC-011</td><td>PA-CAT-01 Momento de creación del contrato</td><td>Al admitir la solicitud en CRM, en estado Solicitado</td><td>M02, M09</td></tr><tr><td>DEC-012</td><td>PA-CAT-05 Jerarquía del catálogo</td><td>Servicio → producto (subservicio = producto adicional) → plan versionado → conceptos facturables</td><td>M02, M04, M05</td></tr><tr><td>DEC-013</td><td>PA-CAT-10 Modalidad de equipos</td><td>Configurable por plan; comodato por defecto en Internet y TV, valorizado en stock</td><td>M02, M13, M10</td></tr><tr><td>DEC-014</td><td>PA-CFG-P1-05 + PA-CFG-P3-04 Reconexión al pagar</td><td>Automática en servicios remotos al confirmarse el pago y sin deuda vencida del servicio; si requiere técnico, OT automática</td><td>M07, M08, M10</td></tr><tr><td>DEC-015</td><td>PA-CFG-P3-05 Pasarelas en O5</td><td>Pagos360, Mercado Pago, SIRO y Red Link en O5; el resto Extensión en O11</td><td>M07, T06</td></tr><tr><td>DEC-016</td><td>PA-VEN-08 Facturación de la instalación del piloto</td><td>En la primera factura del ciclo tras la OT confirmada (concepto vinculado)</td><td>M11, M05</td></tr><tr><td>DEC-017</td><td>PA-CFG-P1-01 Numeración de titulares</td><td>Secuencia única por tenant con atributo de tipo; número manual solo en migración</td><td>M01, T07</td></tr><tr><td>DEC-018</td><td>PA-CFG-P2-06 ARCA sin respuesta en mostrador</td><td>Espera del CAE con tiempo máximo; luego contingencia CAEA o comprobante pendiente no entregable como fiscal</td><td>M05, M06, M11</td></tr><tr><td>DEC-019</td><td>PA-INS-03 Ola del capital social</td><td>Mínimo en O5 (rubros, regla, facturado/pagado, estado de cuenta); resto O10</td><td>M17, M05, M07</td></tr><tr><td>DEC-020</td><td>PA-CFG-P1-03 Claves de mapas e IA</td><td>Provistas por la plataforma, con opción de clave propia del tenant</td><td>T01, T06</td></tr><tr><td>DEC-021</td><td>PA-CAT-02 Habilitar y publicar servicios</td><td>Plataforma habilita según licencia; admin del tenant publica con aprobación de otro usuario en producción</td><td>M02, T01</td></tr><tr><td>DEC-022</td><td>PA-CAT-03 Apagar oferta con contratos vigentes</td><td>Cerrar oferta frena altas; cerrar operación exige plan de salida</td><td>M02</td></tr><tr><td>DEC-023</td><td>PA-CAT-04 Altas automáticas</td><td>Directas solo obligatorios con fundamento normativo; opcionales se proponen con consentimiento</td><td>M02, M01</td></tr><tr><td>DEC-024</td><td>PA-CAT-06 Banco de sangre</td><td>Solo administrativo por convenio, sin datos clínicos</td><td>M02, M18</td></tr><tr><td>DEC-025</td><td>PA-CAT-07 Copias entre tenants</td><td>Autorización explícita del tenant origen</td><td>M02, T01</td></tr><tr><td>DEC-026</td><td>PA-CAT-08 Plantillas de plataforma</td><td>Sí, sin precios ni condiciones reguladas</td><td>M02, T01</td></tr><tr><td>DEC-027</td><td>PA-CAT-09 Provisorio</td><td>Suministro transitorio con vencimiento obligatorio, facturable en esa condición</td><td>M02, M05</td></tr><tr><td>DEC-028</td><td>PA-CAT-11 Contratos iguales en una cuenta</td><td>Permitido en no medidos; en medidos uno por punto de suministro</td><td>M02, M03</td></tr><tr><td>DEC-029</td><td>PA-CAT-12 Deuda previa en el domicilio</td><td>Advertencia con autorización opcional; nunca bloqueo ni traslado de deuda</td><td>M02, M07</td></tr><tr><td>DEC-030</td><td>PA-CAT-13 Modalidades de gas</td><td>Red natural, propano por red y envasado, habilitables por tenant</td><td>M02, M03, M04</td></tr><tr><td>DEC-031</td><td>PA-CAT-14 Suspensión voluntaria</td><td>Configurable por servicio, deshabilitada por defecto</td><td>M02, M08</td></tr><tr><td>DEC-032</td><td>PA-CAT-15 Vigencia del cambio de plan</td><td>Próximo período; inmediato con prorrateo si el tenant lo habilita</td><td>M02, M04</td></tr><tr><td>DEC-033</td><td>PA-CAT-16 Hecho de activación</td><td>Confirmación técnica de instalación y aprovisionamiento; revisión del supervisor posterior</td><td>M02, M10, M05</td></tr><tr><td>DEC-034</td><td>PA-FAC-01 Modalidad de factura por defecto</td><td>Separada por servicio; agrupada multiservicio solo si se activa por grupo</td><td>M05</td></tr><tr><td>DEC-035</td><td>PA-FAC-04 Asignación del número fiscal</td><td>Al emitir, en orden del lote. Comprobante rechazado por ARCA: <strong>reemplazada en ese punto por DEC-107</strong> (vuelve a borrador y libera su número; los posteriores sin CAE se renumeran desde el último autorizado). <em>Reemplazado (DEC-107, 10-11-2026): &quot;si ARCA rechaza se reenvía el mismo número&quot;.</em></td><td>M05, M06</td></tr><tr><td>DEC-036</td><td>PA-FAC-05 Factura con total negativo</td><td>Política por servicio; por defecto NC; generación distribuida como crédito a futuro</td><td>M05, M03</td></tr><tr><td>DEC-037</td><td>PA-FAC-06 Factura en cero</td><td>No emitir; registrar &quot;sin cargo&quot;, configurable por servicio</td><td>M05</td></tr><tr><td>DEC-038</td><td>PA-FAC-19 Caída de ARCA en masiva</td><td>Emitir y encolar; pausar solo la autorización; CAEA si está habilitado</td><td>M05, M06, T06</td></tr><tr><td>DEC-039</td><td>PA-TEC-01 Cierre de OT</td><td>Dos pasos por defecto en altas, desconexiones, reconexiones y cambios de medidor; configurable por operación</td><td>M10</td></tr><tr><td>DEC-040</td><td>PA-TEC-04 Factibilidad obligatoria</td><td>Configurable por servicio; obligatoria por defecto en Internet y servicios con red</td><td>M10, M02</td></tr><tr><td>DEC-041</td><td>PA-TEC-09 Aprovisionamiento</td><td>Automático asíncrono vía conector con respaldo manual</td><td>M10, T06</td></tr><tr><td>DEC-042</td><td>PA-TEC-10 Sistemas de red del piloto</td><td>MikroTik, Radius y SmartOLT en O3</td><td>M10, T06</td></tr><tr><td>DEC-043</td><td>PA-PER-01 Verificación del vínculo usuario-titular</td><td>Código de factura + documento, código al contacto o validación presencial, con intentos limitados</td><td>M01, M19, T02</td></tr><tr><td>DEC-044</td><td>PA-PER-02 Documento duplicado</td><td>Único por tenant, con excepción aprobada y auditada</td><td>M01</td></tr><tr><td>DEC-045</td><td>PA-PER-06 Deuda en cambio de titularidad</td><td>Queda en el saliente; el nuevo solo la asume por convenio</td><td>M01, M07, M08</td></tr><tr><td>DEC-046</td><td>PA-PER-13 Proveedor geográfico</td><td>Georef para normalizar/geocodificar; Google Maps para mapa y autocompletado</td><td>M01, T04, T06</td></tr><tr><td>DEC-047</td><td>Política de preguntas</td><td>Se preguntan solo las de alto impacto o que bloquean olas tempranas; las de detalle se asumen con la opción recomendada y quedan <code>Asumida (recomendada)</code> para revisión posterior</td><td>Todos</td></tr><tr><td>DEC-048</td><td>PA-COB-01 Imputación de pagos</td><td>Por antigüedad, recargos/intereses primero, respetando elección explícita del socio o cajero</td><td>M07</td></tr><tr><td>DEC-049</td><td>PA-COB-03 Créditos entre servicios</td><td>Automático solo dentro del mismo servicio; entre servicios con elección o autorización</td><td>M07</td></tr><tr><td>DEC-050</td><td>PA-COB-09 Identificador de pago en la migración</td><td>Identificador nuevo autocontenido + resolución por clave ProCoop hasta vencer sus facturas</td><td>M07, M05, T07</td></tr><tr><td>DEC-051</td><td>PA-CFG-P1-04 Interés en pago online de factura vencida</td><td>Diferido a la próxima factura, configurable por canal</td><td>M07, M08</td></tr><tr><td>DEC-052</td><td>PA-CFG-P3-01 Plazo de prescripción de deuda</td><td>Plazos <strong>por tipo de obligación</strong> (<code>prescriptionRules</code>): <strong>24 meses</strong> para facturas periódicas de servicios (CCyC art. 2562 inc. c) y <strong>60 meses</strong> para el resto (ventas, cuotas de convenio, otros; CCyC art. 2560). Todo es editable por tenant y servicio y requiere validación legal (<code>validationStatus</code>) antes de la primera corrida productiva. <em>Revisada el 04-11-2026: el solicitante había elegido 5 años para todo y, ante la observación sobre el art. 2562, confirmó la diferenciación.</em></td><td>M08, M07, T04b parte 3</td></tr><tr><td>DEC-053</td><td>PA-FIS-03 Certificado ARCA</td><td>La plataforma genera clave y CSR (clave privada en bóveda) y admite PFX existente</td><td>M06, T06</td></tr><tr><td>DEC-054</td><td>PA-FIS-09 Jurisdicciones de IIBB</td><td>Córdoba en O4; resto como configuración en O8</td><td>M06</td></tr><tr><td>DEC-055</td><td>PA-CRM-06 Proveedor de WhatsApp</td><td>Meta Cloud API por defecto, adaptador para Trii</td><td>M09, T06, T09</td></tr><tr><td>DEC-056</td><td>PA-CRM-09 IA en atención</td><td>Clasificar/resumir/sugerir en O6; adjuntos en O10; apagada hasta aceptación del tenant</td><td>M09</td></tr><tr><td>DEC-057</td><td>PA-CRM-15 Botón de baja</td><td>Habilitado en Internet, TV y telefonía; configurable en otros; código en 24 h</td><td>M09, M19</td></tr><tr><td>DEC-058</td><td>PA-SUE-01 Estrategia de sueldos</td><td>O8 importación de liquidador externo; O9 liquidación propia con 2 períodos en paralelo</td><td>M16, M15, M14</td></tr><tr><td>DEC-059</td><td>PA-TES-16 Tesorería en O5</td><td>Cuentas, rendición, depósitos, extractos y conciliación en O5; valores, cupones, retenciones e Interbanking en O8</td><td>M14</td></tr><tr><td>DEC-060</td><td>PA-MED-08 Generación distribuida</td><td>Configurable por régimen; default compensación monetaria (Ley 27.424)</td><td>M03, M04, M05</td></tr><tr><td>DEC-061</td><td>PA-INS-02 Capital social en la factura</td><td>Renglón identificado en la factura del servicio con auxiliar separado y leyenda</td><td>M17, M05</td></tr><tr><td>DEC-062</td><td>PA-PLA-01 Región de alojamiento</td><td>AWS sa-east-1 (San Pablo) con cláusulas contractuales de transferencia internacional según la AAIP; diseño agnóstico de nube (DEC-004; antes citaba DEC-008, que es el modelo del muro)</td><td>T01, T08</td></tr><tr><td>DEC-063</td><td>PA-PLA-02/03 Continuidad y niveles de servicio</td><td>Disponibilidad 99,5 % mensual; RPO ≤ 15 min; RTO ≤ 4 h por tenant y ≤ 8 h plataforma completa; p95 interactivo ≤ 800 ms; soporte lunes a viernes 8–18 con P1 24×7</td><td>T01, T08</td></tr><tr><td>DEC-064</td><td>PA-PLA-14 Varias personas jurídicas por tenant</td><td>Sí: <code>legalEntities</code> del tenant (equivalente a <code>EMPRESAS</code> de ProCoop), gestionadas en T04, con emisión, contabilidad y sueldos por entidad; <code>legalEntityId</code> en los documentos económicos desde O0. Completada por DEC-096 (membresías de asociados, centros de costo, alcance de roles, auditoría y ámbito de parámetros)</td><td>T01, T04, T05, M05, M06, M15, M16</td></tr><tr><td>DEC-065</td><td>PA-PLA-08/09 Modelo comercial y facturación del SaaS</td><td>Packs por tamaño + complementos con cupo por contratos activos; facturación con M05 bajo el tenant <code>PLATFORM</code> desde O5 y prefactura exportable en O1</td><td>T01, M05</td></tr><tr><td>DEC-066</td><td>PA-IAM-01 Ingreso del socio</td><td>Contraseña o código OTP de 6 dígitos por correo/SMS habilitable por tenant; sin enlace mágico</td><td>T02, M19</td></tr><tr><td>DEC-067</td><td>PA-IAM-02 CiDi Córdoba</td><td>Mecanismo de proveedor federado en O1; CiDi habilitable por tenant al publicar el portal (O2); nivel mínimo 2 para vincular cuentas</td><td>T02, T06, M19</td></tr><tr><td>DEC-068</td><td>PA-MIG-04 Orden de reemplazo de ProCoop</td><td>Por etapas: corte comercial (M01–M09) primero; contabilidad, compras, stock, tesorería y sueldos siguen en ProCoop hasta el corte administrativo</td><td>T07</td></tr><tr><td>DEC-069</td><td>PA-CON-03 y PA-MIG-18 Contabilidad durante la convivencia</td><td>Oficial en ProCoop hasta el corte administrativo; CoopApps contabiliza en un plan marcado no oficial, concilia contra ProCoop y se oficializa en el corte</td><td>M15, T07</td></tr><tr><td>DEC-070</td><td>PA-MIG-01 Profundidad del histórico</td><td>Ejercicio en curso + 24 meses en estructuras tipadas; el resto en <code>legacyRecords</code> consultables; copia del origen conservada 10 años</td><td>T07</td></tr><tr><td>DEC-071</td><td>PA-SOC-14 Ola de adherentes</td><td>Adherentes y sus entradas a facturar (<code>billing-inputs</code>) en O4; el resto de M18 en O10</td><td>M18, M05</td></tr><tr><td>DEC-072</td><td>Preguntas no consultadas (política DEC-047)</td><td>Toda PA de <code>02-preguntas-abiertas.md</code> marcada &quot;Asumida (DEC-072)&quot; adopta su opción recomendada; el usuario puede revisarla en cualquier momento</td><td>Todos</td></tr><tr><td>DEC-073</td><td>Cómo queda especificado cada servicio de punta a punta</td><td>Nuevo anexo <code>T12-SRV-fichas-verticales-servicios.md</code>: una ficha por cada uno de los 17 dominios de M02 §6.C (INT, TEL, TV, ELE, AG, CLO, GAS, ALU, OBR, SEP, CEM, SAN, SAL, VIV, TAS, CAP, OTR) que recorre contrato, medición, tarifa, facturación, fiscal, cobro, mora, técnica, atención, portal, reportes y migración, con IDs exactos de cada anexo. Se arma cuando estén completos todos los anexos y sirve de control de cobertura</td><td>T12, M02–M19</td></tr><tr><td>DEC-074</td><td>PA-INT-02 Bóveda de secretos</td><td>Cifrado por sobre (envelope encryption) propio en MongoDB con clave maestra en AWS KMS, detrás de una interfaz agnóstica de proveedor; nunca se transcriben ni registran valores</td><td>T06, T01, T08</td></tr><tr><td>DEC-075</td><td>PA-NFR-03 Perfil de capacidad</td><td>Tenant estándar 25.000 suministros y grande 150.000; diseño para 100 tenants y hasta 300 sin rediseño</td><td>T08, T01</td></tr><tr><td>DEC-076</td><td>PA-NFR-07 Rol ante la Ley 25.326</td><td>GoodApps es prestador de servicios de tratamiento por cuenta de la cooperativa (art. 25): contrato tipo de encargo, registro público de subencargados, destrucción o devolución al fin del encargo</td><td>T08, T01</td></tr><tr><td>DEC-077</td><td>PA-COM-04 Contratación de mensajería</td><td>Dos modelos: conector propio del tenant, o proveedor de plataforma revendido con consumo medido como complemento del pack (DEC-065)</td><td>T09, T06, T01</td></tr><tr><td>DEC-078</td><td>PA-INT-22 y PA-WFL-06 Firma de documentos</td><td>Firma electrónica con OTP por defecto (instalación, convenios, trámites); firma digital con proveedor licenciado solo para recibos de sueldo y actas (O8/O9); interfaz de firma propia y proveedor elegido antes de O3</td><td>T11, T06, M16, M17</td></tr><tr><td>DEC-079</td><td>PA-WFL-04 Diseñador de trámites</td><td>El tenant ajusta plantillas de plataforma en puntos de extensión y crea trámites nuevos solo de tipo &quot;solicitud genérica&quot; que terminan en tarea o caso</td><td>T11</td></tr><tr><td>DEC-080</td><td>PA-WFL-05 Motor de PDF</td><td>HTML + CSS renderizado con Chromium sin interfaz en workers dedicados, con validación PDF/A posterior</td><td>T11, T03, T08</td></tr><tr><td>DEC-081</td><td>Cooperativa piloto</td><td>La cooperativa piloto (comercial y de migración) <strong>no está definida</strong>; los anexos la nombran &quot;cooperativa piloto&quot;. Laguna Larga (<code>LAG</code>, base <code>PR_LAG_DEMO</code>) es solo la <strong>base relevada de referencia</strong> de ProCoop: sus configuraciones, formatos (Red Link, SIRO) y valores se usan para el mapeo, las pruebas de paralelo y los <code>[VERIFICAR]</code>, no como piloto. Los requisitos marcados para LAG aplican a toda cooperativa migrada con la misma configuración. <strong>Reemplazada por DEC-088</strong></td><td>T07, M07, T06, todos</td></tr><tr><td>DEC-082</td><td>PA-CAT-17 Gas envasado</td><td>En alcance como variante &quot;envasado&quot; de GAS: venta con stock (M13) y entrega (M10), sin medidor; habilitable por tenant</td><td>M02, M13, M10, M04</td></tr><tr><td>DEC-083</td><td>PA-CAT-18 Conceptos de terceros sin servicio propio</td><td>Siempre cuelgan de un contrato propio del socio con perfil &quot;convenio de terceros&quot; accesorio</td><td>M02, M06, M08, T07</td></tr><tr><td>DEC-084</td><td>PA-CAT-19 Correo electrónico y pack SMS</td><td>Servicios de M02 con aprovisionamiento por T06 y cupo/consumo; habilitables por tenant</td><td>M02, T06, M04, M10</td></tr><tr><td>DEC-085</td><td>Corrección de volumen de gas (HUE-GAS-03)</td><td>La aplica M04 con sus factores; M03 entrega el volumen medido (asumida por coherencia con PA-TAR-19)</td><td>M04, M03</td></tr><tr><td>DEC-086</td><td>Destino de <code>BENSOC</code> (HUECO-SEP-02)</td><td>Único destino <code>serviceBeneficiaries</code> de M18; no es tarifa social</td><td>M18, T07, T05, M02, M04, T09</td></tr><tr><td>DEC-087</td><td>PA-DAT-01 y PA-DAT-02</td><td>Cuenta corriente por titular y entidad jurídica con recibo por entidad; histórico de más de 36 meses en consulta diferida (asumidas, DEC-072)</td><td>T05, M07, M05, T08</td></tr><tr><td>DEC-088</td><td>Cooperativa piloto (reemplaza DEC-081)</td><td>La cooperativa piloto comercial y de migración es Laguna Larga (<code>LAG</code>), que sigue siendo la base relevada de referencia; Internet sigue siendo el primer servicio construido (DEC-005); primera migración real de LAG después de O7, con prepago disponible, y corte por etapas hasta O11</td><td>00, T07, M07, T06, 02, 04, todos</td></tr><tr><td>DEC-089</td><td>Corte comercial y servicios de LAG</td><td>Electricidad, gas y prepago de LAG se cortan tras el cierre de O7 con 2 ciclos de paralelo aprobados; otros servicios que aparezcan en el perfilado, al cierre de la ola de su vertical; corte administrativo y apagado de ProCoop en O11 (DEC-068)</td><td>T07, M07, 00</td></tr><tr><td>DEC-090</td><td>Formato del <code>type</code> de errores RFC 9457</td><td><code>type</code> relativo <code>/problems/&amp;lt;módulo&gt;/&amp;lt;código&gt;</code> resuelto contra el portal de desarrolladores de T10; reemplaza la forma <code>https://goodapps.ar/errors/...</code> de M01</td><td>T08, M01, T07, T10, M06</td></tr><tr><td>DEC-091</td><td>Tokenización de tarjetas y alcance PCI DSS</td><td>GoodApps nunca recibe ni guarda PAN, vencimiento ni CVV (alcance SAQ A); el débito con tarjeta guarda solo token opaco, marca y últimos 4; procesadoras por archivo solo con número de adherente; los PAN de ProCoop no se migran (identificador existente, tokenización masiva del proveedor o re-adhesión)</td><td>M07, T06, T07, T08, T05, M19</td></tr><tr><td>DEC-092</td><td>Cierre de brechas del modelo de amenazas</td><td>PDF con render aislado; CA privada para certificados del agente (90 días, renovación automática); tenant de webhooks por <code>endpointKey</code>; extracción ProCoop solo saliente y cifrada; credenciales heredadas regeneradas; DEK y colecciones globales alineadas con T05; contraseña socio 10 / personal 12, máximo 128; retiro de dominios propios; momento del pentest; semilla de tenants de prueba desde O0</td><td>T08, T06, T07, T01, T05</td></tr><tr><td>DEC-093</td><td>Factura agrupada y LQSP (PA-FIS-23)</td><td>La factura agrupada no mezcla la liquidación de servicios públicos (LQSP) con la factura común: un documento por tipo de comprobante; dentro de la LQSP solo los conceptos accesorios que el tenant declare con el contador. Corrige RN-FAC-040</td><td>M05, M06</td></tr><tr><td>DEC-094</td><td>Vía de autorización de la LQSP (PA-FIS-24)</td><td>Se mantiene CESP separado del CAEA; la norma y el efecto de las RG 5003 y 5866/2026 quedan para el contador</td><td>M06, M05</td></tr><tr><td>DEC-095</td><td>Obligaciones propias de la cooperativa (PA-FIS-25)</td><td>Registro genérico en M06 de obligaciones y exenciones propias del tenant como contribuyente, sin precarga de normas; M17 provee la base de capital y M15 contabiliza</td><td>M06, M17, M15</td></tr><tr><td>DEC-096</td><td>Varias entidades jurídicas: alcance completo (completa DEC-064)</td><td><code>legalEntityId</code> en membresías de asociados, centros de costo, alcance de roles y auditoría; ámbito <code>legalEntity</code> en los parámetros</td><td>M17, M15, T02, T04, T05</td></tr><tr><td>DEC-097</td><td>Persona única en todos los maestros</td><td><code>personId</code> obligatorio en proveedores, vendedores, choferes y profesionales, con alta asistida de M01 y control de duplicados. Cambia RN-CMP-001</td><td>M12, M11, M18, M01, T07</td></tr><tr><td>DEC-098</td><td>Origen de las sucursales en la migración</td><td>Las sucursales se derivan de <code>PTOVENTA.SUC_COM</code> y las confirma la cooperativa; RF-CFG-142 deja de citar <code>EMPRESAS</code> y <code>CAJASJP</code></td><td>T04, T07</td></tr><tr><td>DEC-099</td><td>Personas migradas sin documento</td><td>Estado <code>documentPending</code>, fuera del control de duplicados por documento, con tarea de regularización y sin comprobantes que exijan identificarlas por documento</td><td>T07, M01, M05</td></tr><tr><td>DEC-100</td><td>Verificador de integridad referencial</td><td>Proceso nocturno por tenant que informa referencias rotas sin corregirlas, con bandeja y alerta; reemplaza la propuesta de claves foráneas, incompatible con DEC-001</td><td>T05, T08</td></tr><tr><td>DEC-101</td><td>Cajas sin rendir en la posición de tesorería</td><td>Línea separada &quot;en cajas sin rendir&quot; en la posición diaria de M14, leída del servicio de M07; no se suma a lo rendido</td><td>M14, M07</td></tr><tr><td>DEC-102</td><td>Uso del suministro en la alícuota de IVA (PA-FIS-26)</td><td>Condición opcional de <code>vatRateMatrix</code>, desactivada por defecto hasta que confirme el contador</td><td>M06, M01</td></tr><tr><td>DEC-103</td><td>Supresión de secretos en la migración (amplía DEC-091 y DEC-092)</td><td>Más credenciales que no se migran y escaneo previo de tarjetas (Luhn) y credenciales que bloquea la migración hasta clasificar la columna</td><td>T07, T08</td></tr><tr><td>DEC-104</td><td>Correcciones internas del contraste</td><td>Correcciones sin cambio de alcance (<code>USERS_AREA</code>, <code>RESPONSA</code>, <code>PROD_SER</code>, <code>TIPO_FAC</code>, prorrateo de M04, <code>numberSequences</code>, <code>recordLinks</code>, IVR, tablas de M07)</td><td>M01, M04, M05, M07, M08, T04, T06, T07, T09</td></tr><tr><td>DEC-105</td><td>Fórmulas en tarifas</td><td>Se mantienen las fórmulas con preferencia declarativa: justificación obligatoria por regla e informe por tenant de reglas con fórmula</td><td>M04</td></tr><tr><td>DEC-106</td><td>Tope de vencimientos por comprobante</td><td>De 1 a 4 por defecto; el tope es parámetro del tenant, validado contra los formatos de código de barras y los layouts de los entes. Amplía RF-FAC-086</td><td>M05, M07</td></tr><tr><td>DEC-107</td><td>Comprobante rechazado por ARCA (reemplaza DEC-035 en ese punto)</td><td>Vuelve a borrador y libera su número; los posteriores sin CAE se renumeran desde el último autorizado; nada se imprime, envía ni publica sin CAE, CAEA informado o CESP; auditoría de cada número</td><td>M05, M06, M07</td></tr><tr><td>DEC-108</td><td>GestionApps como sistema base</td><td>No es fuente hoy por falta de información; posible fuente a analizar en el futuro (§2.3)</td><td>00</td></tr></tbody></table><hr><h2 id="_4-alcance-funcional" tabindex="-1">4. Alcance funcional <a class="header-anchor" href="#_4-alcance-funcional" aria-label="Permalink to &quot;4. Alcance funcional&quot;">​</a></h2><h3 id="_4-1-soluciones-base-§105-y-su-materializacion" tabindex="-1">4.1 Soluciones (BASE §105) y su materialización <a class="header-anchor" href="#_4-1-soluciones-base-§105-y-su-materializacion" aria-label="Permalink to &quot;4.1 Soluciones (BASE §105) y su materialización&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Solución</th><th>Módulos/anexos que la materializan</th></tr></thead><tbody><tr><td>ERP</td><td>M01 PER, M02 CAT, M03 MED, M04 TAR, M05 FAC, M06 FIS, M07 COB, M08 MOR, M11 VEN, M12 CMP, M13 STK, M14 TES, M15 CON, M16 SUE, M17 INS, M18 SOC</td></tr><tr><td>CRM</td><td>M09 CRM, M10 TEC, T09 COM</td></tr><tr><td>Landing y autogestión</td><td>M19 POR, T03 UXD, T09 COM</td></tr><tr><td>Plataforma SaaS</td><td>T01 PLA, T02 IAM, T04 CFG, T08 NFR</td></tr><tr><td>Cobranza</td><td>M07 COB, M08 MOR</td></tr><tr><td>Pasarelas</td><td>M07 COB + T06 INT</td></tr><tr><td>Liquidación de impuestos</td><td>M06 FIS (+ M15 CON para regímenes contables)</td></tr><tr><td>APIs</td><td>T10 BIA, T06 INT</td></tr><tr><td>Soporte transversal</td><td>T05 DAT, T07 MIG, T11 WFL</td></tr></tbody></table><h3 id="_4-2-servicios-cubiertos-todos-configurables-por-tenant" tabindex="-1">4.2 Servicios cubiertos (todos configurables por tenant) <a class="header-anchor" href="#_4-2-servicios-cubiertos-todos-configurables-por-tenant" aria-label="Permalink to &quot;4.2 Servicios cubiertos (todos configurables por tenant)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Familia</th><th>Servicios</th><th>Particularidades</th><th>Ola</th></tr></thead><tbody><tr><td>TIC</td><td>Internet (fibra, inalámbrico, cable), telefonía fija/IP con tasación de CDR, TV (cable/IPTV), servicios de datos</td><td>Aprovisionamiento (MikroTik/Radius/OLT), equipos en comodato, planes y velocidades</td><td>Internet O3–O6; telefonía y TV O10</td></tr><tr><td>Medidos</td><td>Electricidad (incl. generación distribuida, grandes usuarios, demanda, factor de potencia), agua, gas, cloacas</td><td>Medidores, rutas, lecturas, tramos, cargos con fórmulas, reguladores, compra de energía</td><td>O7</td></tr><tr><td>Fijos/abonos</td><td>Sepelio, cementerio parque, ambulancia/emergencias, banco de sangre, seguros/adhesiones, cuotas sociales</td><td>Grupo familiar, adherentes, carencias</td><td>O10 (cuota social O2–O4)</td></tr><tr><td>Sociales y otros</td><td>Planes de vivienda, salud, actividades, ventas de productos, fabricación (postes, bloques u otros), traslados y flota</td><td>Contratos, cuotas, órdenes de producción</td><td>O10</td></tr></tbody></table><h3 id="_4-3-correspondencia-de-los-29-modulos-de-procoop-dfa-con-los-anexos" tabindex="-1">4.3 Correspondencia de los 29 módulos de ProCoop (DFA) con los anexos <a class="header-anchor" href="#_4-3-correspondencia-de-los-29-modulos-de-procoop-dfa-con-los-anexos" aria-label="Permalink to &quot;4.3 Correspondencia de los 29 módulos de ProCoop (DFA) con los anexos&quot;">​</a></h3><p>Ningún módulo de ProCoop se pierde. Se reagrupan para que cada entidad tenga un único dueño de datos (ARQ-01). La trazabilidad línea por línea está en la sección 22 de cada anexo.</p><table tabindex="0"><thead><tr><th>DFA</th><th>Módulo ProCoop</th><th>Prioridad ProCoop</th><th>Anexo(s) CoopApps</th><th>Ola</th></tr></thead><tbody><tr><td>M1</td><td>Plataforma, seguridad y auditoría</td><td>A</td><td>T01 PLA, T02 IAM</td><td>O0–O1</td></tr><tr><td>M2</td><td>Parámetros y tablas maestras</td><td>A</td><td>T04 CFG, T04b (1.536 parámetros)</td><td>O1</td></tr><tr><td>M3</td><td>Personas, titulares y cuentas</td><td>A</td><td>M01 PER</td><td>O2</td></tr><tr><td>M4</td><td>Catálogo de servicios, categorías y conexiones</td><td>A</td><td>M02 CAT</td><td>O2</td></tr><tr><td>M5</td><td>Medidores y equipos de medición</td><td>A</td><td>M03 MED</td><td>O7 (equipos TIC en O3 vía M13)</td></tr><tr><td>M6</td><td>Lecturas, consumos y telemedición</td><td>A</td><td>M03 MED</td><td>O7</td></tr><tr><td>M7</td><td>Cuadros tarifarios y motor de cálculo</td><td>A</td><td>M04 TAR</td><td>O4, O7</td></tr><tr><td>M8</td><td>Facturación de servicios y comprobantes electrónicos</td><td>A</td><td>M05 FAC, M06 FIS</td><td>O4</td></tr><tr><td>M9</td><td>Cuenta corriente del titular</td><td>A</td><td>M07 COB</td><td>O5</td></tr><tr><td>M10</td><td>Cobranza: cajas, medios de pago y entes recaudadores</td><td>A</td><td>M07 COB, T06 INT</td><td>O5</td></tr><tr><td>M11</td><td>Gestión de mora y corte</td><td>A</td><td>M08 MOR</td><td>O6</td></tr><tr><td>M12</td><td>Financiación y planes de pago</td><td>B</td><td>M08 MOR</td><td>O6</td></tr><tr><td>M13</td><td>Ventas, presupuestos y punto de venta</td><td>B</td><td>M11 VEN</td><td>O4–O8</td></tr><tr><td>M14</td><td>Técnica: factibilidades, órdenes de trabajo y reclamos</td><td>B</td><td>M10 TEC (reclamos: M09 CRM)</td><td>O3</td></tr><tr><td>M15</td><td>Redes e infraestructura (GIS)</td><td>C</td><td>M10 TEC</td><td>O3, O7</td></tr><tr><td>M16</td><td>Compras y proveedores</td><td>B</td><td>M12 CMP</td><td>O8</td></tr><tr><td>M17</td><td>Stock, bienes de uso, RMA y fabricación</td><td>B</td><td>M13 STK</td><td>O3 (serializado), O8, O10</td></tr><tr><td>M18</td><td>Tesorería y bancos</td><td>B</td><td>M14 TES</td><td>O8</td></tr><tr><td>M19</td><td>Contabilidad</td><td>B</td><td>M15 CON</td><td>O5 (núcleo), O8</td></tr><tr><td>M20</td><td>Sueldos y personal</td><td>C</td><td>M16 SUE</td><td>O9</td></tr><tr><td>M21</td><td>Atención: mesa de entradas, turnero y comunicaciones</td><td>B</td><td>M09 CRM, T09 COM</td><td>O2–O3, O10</td></tr><tr><td>M22</td><td>Actividades y tareas internas</td><td>C</td><td>M09 CRM, T11 WFL</td><td>O1–O2, O10</td></tr><tr><td>M23</td><td>Traslados y flota</td><td>C</td><td>M18 SOC</td><td>O10</td></tr><tr><td>M24</td><td>Gestión institucional</td><td>C</td><td>M17 INS</td><td>O10</td></tr><tr><td>M25</td><td>Servicios sociales y otros servicios</td><td>C</td><td>M18 SOC</td><td>O10</td></tr><tr><td>M26</td><td>Autogestión del socio: portal y app</td><td>B</td><td>M19 POR</td><td>O2+</td></tr><tr><td>M27</td><td>App móvil de campo</td><td>B</td><td>M10 TEC (técnico), M03 MED (lecturista), M07 COB (cobrador), T03 UXD (AppShell)</td><td>O3, O5, O7</td></tr><tr><td>M28</td><td>Reportes, tableros y exportaciones</td><td>B</td><td>T10 BIA (+ sección 15 de cada anexo)</td><td>O1–O11</td></tr><tr><td>M29</td><td>Integraciones externas</td><td>A/B</td><td>T06 INT</td><td>O0–O11</td></tr></tbody></table><p>Las prioridades A/B/C de ProCoop no excluyen nada (DEC-007): solo influyen en la ola.</p><h3 id="_4-4-exclusiones" tabindex="-1">4.4 Exclusiones <a class="header-anchor" href="#_4-4-exclusiones" aria-label="Permalink to &quot;4.4 Exclusiones&quot;">​</a></h3><p>No hay exclusiones funcionales (DEC-007). Lo único que no se replica son las <strong>deudas técnicas y de seguridad de ProCoop</strong>, que se reemplazan por la mejora indicada en cada anexo:</p><ul><li>contraseñas reversibles;</li><li>usuario SQL compartido;</li><li>secretos hardcodeados;</li><li>una base de datos por cooperativa;</li><li>sincronización con MySQL externa para CoopOnline;</li><li>instalación local y actualizaciones manuales;</li><li>menú construido por reflexión;</li><li>parámetros numéricos sin semántica.</li></ul><hr><h2 id="_5-arquitectura-y-stack-tecnologico" tabindex="-1">5. Arquitectura y stack tecnológico <a class="header-anchor" href="#_5-arquitectura-y-stack-tecnologico" aria-label="Permalink to &quot;5. Arquitectura y stack tecnológico&quot;">​</a></h2><p>Norma vigente para implementación con GoodApps: <strong>DEC-111</strong>, <strong>DEC-112</strong>, <strong>DEC-113</strong>, <strong>DEC-117</strong>. Detalle y checklist documental: <code>06-impacto-adaptacion-stack-goodapps.md</code>. Modelo físico: <code>07-modelo-relacional-azure-sql.md</code>.</p><h3 id="_5-1-stack" tabindex="-1">5.1 Stack <a class="header-anchor" href="#_5-1-stack" aria-label="Permalink to &quot;5.1 Stack&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capa</th><th>Tecnología</th><th>Notas</th></tr></thead><tbody><tr><td>Backend</td><td><strong>C# / .NET 10</strong>, ASP.NET Core</td><td>Monolito modular; servicios de dominio; acceso con <strong>EF Core</strong></td></tr><tr><td>Validación</td><td><strong>Zod</strong> en front; validación en API alineada a contratos</td><td>Esquemas compartidos donde aplique; errores RFC 9457</td></tr><tr><td>Base de datos</td><td><strong>Azure SQL</strong> (base compartida multitenant)</td><td><strong>PK/FK/constraints</strong>; transacciones para operaciones económicas; dinero en <code>decimal</code></td></tr><tr><td>Colas y jobs</td><td><strong>Azure Queue Storage</strong> + workers; <strong>Redis</strong> donde aplique</td><td>Facturación masiva, integraciones, notificaciones, reportes, importaciones</td></tr><tr><td>Eventos</td><td>Outbox transaccional + despachador a colas</td><td>Catálogo de eventos y jobs en T11; infraestructura en T01</td></tr><tr><td>Archivos</td><td><strong>Azure Blob</strong> privado; URL firmadas de corta duración</td><td>Facturas PDF, adjuntos, fotos de campo, exportaciones</td></tr><tr><td>Frontend admin</td><td><strong>Vite, React 19, TypeScript</strong>, Tailwind 4, shadcn/Radix, TanStack Query, zustand, react-hook-form</td><td>Comportamiento y shells según T03 (DEC-113)</td></tr><tr><td>PWA / Landing</td><td>React 19 + Vite; PWA instalable; offline con cola idempotente</td><td>Socio, empleado, técnico, lecturista, cobrador; landing pública (M19)</td></tr><tr><td>Identidad</td><td><strong>OpenIddict</strong></td><td>Sesiones, tokens, 2FA según T02</td></tr><tr><td>API</td><td><strong>OpenAPI</strong> generado desde código; contrato de diseño en GACAC (entregables)</td><td>Rutas admin, plataforma, público, ext</td></tr><tr><td>Secretos</td><td>Bóveda con cifrado por sobre y <strong>Azure Key Vault</strong> (DEC-074 alineado a Azure)</td><td>ARCA, pasarelas, bancos, mensajería por tenant (T06)</td></tr><tr><td>Firma</td><td>Firma electrónica con OTP; firma digital con proveedor licenciado (DEC-078)</td><td>T11</td></tr><tr><td>Observabilidad</td><td><strong>Application Insights</strong>, logs estructurados, OpenTelemetry</td><td><code>tenantId</code>, <code>requestId</code>, <code>userId</code> (T08)</td></tr><tr><td>Pruebas</td><td>Unitarias, integración con <strong>Azure SQL</strong> (local/container), contrato, e2e Playwright, carga</td><td>Aislamiento multitenant en CI obligatorio (T08)</td></tr><tr><td>Despliegue</td><td><strong>Microsoft Azure</strong> — Container Apps en red privada (DEC-112); local con contenedores</td><td>T01; transferencia de datos según AAIP (DEC-062 actualizado con región Azure acordada)</td></tr></tbody></table><h3 id="_5-2-estructura-de-referencia-detalle-en-t01-y-repo-goodapps" tabindex="-1">5.2 Estructura de referencia (detalle en T01 y repo GoodApps) <a class="header-anchor" href="#_5-2-estructura-de-referencia-detalle-en-t01-y-repo-goodapps" aria-label="Permalink to &quot;5.2 Estructura de referencia (detalle en T01 y repo GoodApps)&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>coodo/  (referencia GoodApps)</span></span>
<span class="line"><span>  src/</span></span>
<span class="line"><span>    Api/                       # ASP.NET Core: /api, admin, platform, public, ext</span></span>
<span class="line"><span>    Modules/&lt;cod&gt;/             # per, cat, med, tar, fac, … — dueño de esquema/tablas</span></span>
<span class="line"><span>      Domain/  Application/  Infrastructure/  Api/</span></span>
<span class="line"><span>    Workers/                   # consumidores de colas Azure</span></span>
<span class="line"><span>  apps/</span></span>
<span class="line"><span>    admin/                     # React — AdminShell (T03)</span></span>
<span class="line"><span>    pwa/                       # React PWA — AppShell</span></span>
<span class="line"><span>    landing/                   # sitio público por tenant</span></span>
<span class="line"><span>  packages/                    # contratos, enums, capacidades, SDK conectores (T06)</span></span>
<span class="line"><span>  infra/                       # IaC Azure, scripts migración (T07)</span></span>
<span class="line"><span>  docs/                        # análisis exportado desde GACAC</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><h3 id="_5-3-reglas-de-arquitectura" tabindex="-1">5.3 Reglas de arquitectura <a class="header-anchor" href="#_5-3-reglas-de-arquitectura" aria-label="Permalink to &quot;5.3 Reglas de arquitectura&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Regla</th></tr></thead><tbody><tr><td>ARQ-01</td><td>Un módulo solo escribe en sus tablas/esquema; para datos de otro módulo usa su servicio público o reacciona a sus eventos.</td></tr><tr><td>ARQ-02</td><td>Toda operación económica: transacción SQL + evento outbox + <code>Idempotency-Key</code> + auditoría.</td></tr><tr><td>ARQ-03</td><td>Ningún proceso masivo corre en el request HTTP: se encola en un job con progreso, reanudable e idempotente.</td></tr><tr><td>ARQ-04</td><td>Toda consulta lleva <code>TenantId</code> (filtro global EF); jobs, archivos, caché, exportaciones, búsquedas e IA también se aíslan por tenant (DEC-110).</td></tr><tr><td>ARQ-05</td><td>Configuración tipada y versionada (T04), nunca constantes mágicas en el código.</td></tr><tr><td>ARQ-06</td><td>Integraciones solo vía conectores (T06) con credenciales en bóveda.</td></tr><tr><td>ARQ-07</td><td>UI sin textos fijos: claves de diccionario (T03).</td></tr><tr><td>ARQ-08</td><td>La IA solo propone; toda acción con efecto requiere confirmación humana y queda auditada.</td></tr></tbody></table><hr><h2 id="_6-multitenancy-y-plataforma-saas-resumen-detalle-en-t01-y-t02" tabindex="-1">6. Multitenancy y plataforma SaaS (resumen; detalle en T01 y T02) <a class="header-anchor" href="#_6-multitenancy-y-plataforma-saas-resumen-detalle-en-t01-y-t02" aria-label="Permalink to &quot;6. Multitenancy y plataforma SaaS (resumen; detalle en T01 y T02)&quot;">​</a></h2><ul><li><strong>Tenant</strong> = cooperativa. Tenant especial <code>PLATFORM</code> para el operador SaaS.</li><li><strong>Identificación</strong>: subdominio <code>&amp;lt;slug&gt;.dominio</code> o código de cooperativa en el pre-login. Tras el login, el <code>tenantId</code> sale del JWT y nunca de un header manipulable.</li><li><strong>Identidad común con pertenencias</strong>: una persona tiene una sola identidad de acceso y pertenencias privadas por tenant (AGR-006). Por ejemplo, puede ser empleada en la cooperativa A y socia en la B. La selección de ámbito es explícita.</li><li><strong>Ciclo de vida del tenant</strong> (AGR-004): Preparación → Prueba → Listo para habilitar → Operativo → Suspendido administrativo → Cierre/salida. Cada paso tiene checklist de habilitación por capacidad.</li><li><strong>Licenciamiento en capas</strong> (CNX): <ol><li>licencia de módulos contratados por la plataforma;</li><li>activación por el tenant;</li><li>RBAC por rol/perfil;</li><li>alcance de datos.</li></ol></li><li><strong>Soporte</strong>: acceso temporal, consentido y auditado (AGR-034).</li><li><strong>Ambientes</strong>: producción y prueba por tenant con datos anonimizados (AGR-035).</li></ul><hr><h2 id="_7-actores-roles-y-modelo-de-permisos-resumen-matriz-completa-en-t02" tabindex="-1">7. Actores, roles y modelo de permisos (resumen; matriz completa en T02) <a class="header-anchor" href="#_7-actores-roles-y-modelo-de-permisos-resumen-matriz-completa-en-t02" aria-label="Permalink to &quot;7. Actores, roles y modelo de permisos (resumen; matriz completa en T02)&quot;">​</a></h2><h3 id="_7-1-modelo" tabindex="-1">7.1 Modelo <a class="header-anchor" href="#_7-1-modelo" aria-label="Permalink to &quot;7.1 Modelo&quot;">​</a></h3><ul><li><strong>Capability</strong> <code>modulo.recurso.accion</code>. Las acciones estándar son <code>ver</code>, <code>crear</code>, <code>editar</code>, <code>anular</code>, <code>aprobar</code>, <code>exportar</code> y <code>configurar</code>, más las propias de cada módulo.</li><li><strong>Rol funcional</strong> = conjunto de capabilities. <strong>Perfil de pantallas</strong> = qué ítems de menú ve el usuario (BASE §45). El acceso efectivo es la <strong>intersección</strong> de cuatro filtros: <ol><li>licencia del tenant;</li><li>activación del módulo;</li><li>rol;</li><li>alcance de datos.</li></ol></li><li><strong>Alcance de datos</strong>: tenant / sucursales / puntos de venta / zonas / servicios / cuadrillas / depósitos / propios. Reemplaza USERS_AREA, USERS_DEPOSITO y PTO_VTA de ProCoop.</li><li><strong>Controles adicionales</strong>: <ul><li>denegación por defecto;</li><li>separación de funciones;</li><li>autorización de supervisor en el momento o diferida (reemplaza AUTORIZACIONES de ProCoop);</li><li>franja horaria por perfil.</li></ul></li></ul><h3 id="_7-2-catalogo-de-roles" tabindex="-1">7.2 Catálogo de roles <a class="header-anchor" href="#_7-2-catalogo-de-roles" aria-label="Permalink to &quot;7.2 Catálogo de roles&quot;">​</a></h3><p>Catálogo vigente de T02 §4.1 (CTR-IAM-15): los roles de tenant y comunidad son plantillas de plataforma versionadas que cada cooperativa instancia, clona y ajusta (PA-IAM-09); los nombres visibles salen del diccionario. La matriz rol × capability está en T02 §4.3–§4.4.</p><table tabindex="0"><thead><tr><th>Código</th><th>Espacio</th><th>Rol</th><th>Responsabilidad principal</th><th>MFA</th></tr></thead><tbody><tr><td>P-SUP</td><td>Plataforma</td><td>Superadministrador de plataforma</td><td>Tenants, licencias, roles plantilla, usuarios de plataforma, emergencias</td><td>Obligatorio, sin SMS</td></tr><tr><td>P-ADM</td><td>Plataforma</td><td>Administrador de operaciones de tenants</td><td>Alta asistida, configuración base, copia de servicios, migraciones</td><td>Obligatorio, sin SMS</td></tr><tr><td>P-COM</td><td>Plataforma</td><td>Comercial de plataforma</td><td>Contratos SaaS, packs, licencias (sin datos operativos)</td><td>Obligatorio</td></tr><tr><td>P-SOP1</td><td>Plataforma</td><td>Soporte plataforma nivel 1</td><td>Tickets, diagnóstico sin datos; solicita acceso temporal en modo observar</td><td>Obligatorio</td></tr><tr><td>P-SOP2</td><td>Plataforma</td><td>Soporte plataforma nivel 2 / ingeniería</td><td>Acceso temporal observar u operar, acotado y aprobado</td><td>Obligatorio, sin SMS</td></tr><tr><td>P-SEC</td><td>Plataforma</td><td>Seguridad y auditoría de plataforma</td><td>Auditoría global, alertas, incidentes, revisión de accesos</td><td>Obligatorio, sin SMS</td></tr><tr><td>P-OPS</td><td>Plataforma</td><td>Operaciones técnicas (SRE)</td><td>Salud, colas, ambientes, backups (sin datos operativos)</td><td>Obligatorio, sin SMS</td></tr><tr><td>T-ADM</td><td>Tenant</td><td>Administrador de la cooperativa</td><td>Configuración, usuarios, roles, perfiles, políticas, publicación</td><td>Obligatorio</td></tr><tr><td>T-USR</td><td>Tenant</td><td>Administrador de usuarios y seguridad (opcional)</td><td>Alta/baja de usuarios y asignaciones sin operar el negocio (actor CU-29)</td><td>Obligatorio</td></tr><tr><td>T-GER</td><td>Tenant</td><td>Gerente</td><td>Tableros, aprobaciones de alto nivel, lectura general</td><td>Obligatorio</td></tr><tr><td>T-FAC</td><td>Tenant</td><td>Facturación</td><td>Ciclos, lotes, comprobantes, NC/ND, tarifas (propuesta)</td><td>Obligatorio</td></tr><tr><td>T-CAJ</td><td>Tenant</td><td>Cajero</td><td>Caja del turno, cobros, arqueo, ventas de mostrador</td><td>Según política (PRM-IAM-020)</td></tr><tr><td>T-CBR</td><td>Tenant</td><td>Cobrador (campo)</td><td>Cobranza domiciliaria de su cartera, rendición</td><td>Según política</td></tr><tr><td>T-TES</td><td>Tenant</td><td>Tesorero / Financiero (MT-006)</td><td>Bancos, valores, conciliación, pagos, pasarelas</td><td>Obligatorio</td></tr><tr><td>T-CON</td><td>Tenant</td><td>Contador / Contable (MT-006)</td><td>Plan de cuentas, asientos, cierres, fiscal, regímenes</td><td>Obligatorio</td></tr><tr><td>T-CMP</td><td>Tenant</td><td>Compras</td><td>Solicitudes, órdenes de compra, proveedores</td><td>Obligatorio</td></tr><tr><td>T-DEP</td><td>Tenant</td><td>Depósito</td><td>Stock, remitos, equipos serializados, RMA</td><td>Según política</td></tr><tr><td>T-TEC</td><td>Tenant</td><td>Técnico (campo)</td><td>Órdenes asignadas, instalación, firma, fotos, offline</td><td>Según política</td></tr><tr><td>T-LEC</td><td>Tenant</td><td>Lecturista (campo)</td><td>Rutas asignadas y capturas de lectura, offline</td><td>Según política</td></tr><tr><td>T-STE</td><td>Tenant</td><td>Supervisor técnico</td><td>Agenda, cuadrillas, factibilidad, redes/GIS, aprovisionamiento</td><td>Obligatorio</td></tr><tr><td>T-SCM</td><td>Tenant</td><td>Supervisor de consumos (BASE §39.6)</td><td>Validación y corrección justificada de consumos</td><td>Obligatorio</td></tr><tr><td>T-ATE</td><td>Tenant</td><td>Comercial / Atención al socio</td><td>Personas, solicitudes, reclamos, convenios, ventas de mostrador</td><td>Según política</td></tr><tr><td>T-SAT</td><td>Tenant</td><td>Supervisor de atención</td><td>Asignación, derivación, SLA, escalamiento, autorizaciones de atención</td><td>Obligatorio</td></tr><tr><td>T-RRHH</td><td>Tenant</td><td>RRHH / Liquidador</td><td>Legajos, novedades, liquidaciones, recibos</td><td>Obligatorio</td></tr><tr><td>T-SEC</td><td>Tenant</td><td>Secretaría institucional</td><td>Asociados, capital, asambleas, actas</td><td>Obligatorio</td></tr><tr><td>T-COM</td><td>Tenant</td><td>Editor de comunidad / Moderador (USR-NOT-A)</td><td>Muro, novedades, encuestas, moderación</td><td>Según política</td></tr><tr><td>T-SOC</td><td>Tenant</td><td>Operador de servicios sociales y salud</td><td>Sepelio, cementerio, vivienda, ambulancias, banco de sangre (datos sensibles)</td><td>Obligatorio</td></tr><tr><td>T-CJO</td><td>Tenant</td><td>Consejero</td><td>Lectura institucional y agregada, votaciones del consejo</td><td>Obligatorio</td></tr><tr><td>T-SIN</td><td>Tenant</td><td>Síndico / Auditor (solo lectura)</td><td>Lectura amplia + auditoría, sin acciones de escritura</td><td>Obligatorio</td></tr><tr><td>C-SOC</td><td>Comunidad</td><td>Socio titular</td><td>Autogestión de sus cuentas, servicios, pagos, reclamos, comunidad</td><td>Opcional + step-up (PA-IAM-03)</td></tr><tr><td>C-REP</td><td>Comunidad</td><td>Representante / autorizado</td><td>Acciones delegadas por relación vigente (AGR-007)</td><td>Opcional + step-up</td></tr><tr><td>C-ADH</td><td>Comunidad</td><td>Adherente / grupo familiar</td><td>Consulta limitada de servicios sociales propios</td><td>Opcional</td></tr><tr><td>C-VIS</td><td>Comunidad</td><td>Visitante registrado</td><td>Noticias, solicitud de alta, consultas públicas, vinculación de cuentas</td><td>Opcional</td></tr><tr><td>C-EMP</td><td>Comunidad</td><td>Empleado en portal</td><td>Recibos de sueldo, firma de recibo, novedades RRHH</td><td>Opcional + step-up para firma</td></tr><tr><td>C-PRV</td><td>Comunidad</td><td>Proveedor (portal de proveedores)</td><td>Solo por invitación individual del tenant (rol <code>supplier</code>, PA-CMP-05): sus órdenes de compra, carga de facturas y remitos, estado de pagos y retenciones propias (M12 RF-CMP-015, RF-CMP-112)</td><td>Opcional + step-up para datos bancarios</td></tr><tr><td>S-SYS</td><td>Técnico</td><td>Sistema / worker</td><td>Jobs internos con identidad técnica y capabilities por job</td><td>No aplica</td></tr><tr><td>S-API</td><td>Técnico</td><td>Cliente API (integración externa)</td><td>Scopes <code>apiExposable</code> de <code>/api/v1/ext</code></td><td>Credencial técnica</td></tr><tr><td>S-BOT</td><td>Técnico</td><td>Bot / asistente IA</td><td>Actúa con capabilities mínimas propias o <strong>en nombre</strong> de un usuario, nunca más que él</td><td>No aplica</td></tr><tr><td>S-KSK</td><td>Técnico</td><td>Dispositivo kiosco/tótem/turnero</td><td>Operaciones públicas del kiosco; salida del modo kiosco con autenticación de staff</td><td>Enrolamiento de dispositivo</td></tr><tr><td>S-AGT</td><td>Técnico</td><td>Agente de hardware local</td><td>Impresoras fiscales, lectores, balanzas; credencial de dispositivo por puesto</td><td>Enrolamiento de dispositivo</td></tr></tbody></table><p>Total: 40 roles.</p><hr><h2 id="_8-aplicaciones-y-espacios-de-trabajo" tabindex="-1">8. Aplicaciones y espacios de trabajo <a class="header-anchor" href="#_8-aplicaciones-y-espacios-de-trabajo" aria-label="Permalink to &quot;8. Aplicaciones y espacios de trabajo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>App</th><th>Usuarios</th><th>Tecnología/Layout</th><th>Rutas API</th><th>Contenido</th></tr></thead><tbody><tr><td><strong>Admin web</strong> (<code>apps/admin</code>)</td><td>Personal de la cooperativa</td><td>AdminShell, tema oscuro, denso</td><td><code>/api/admin/*</code></td><td>Todos los módulos de gestión M01–M18, configuración, reportes</td></tr><tr><td><strong>Plataforma</strong> (rutas <code>meta.platformOnly</code>)</td><td>Operador SaaS</td><td>AdminShell en modo plataforma</td><td><code>/api/platform/*</code></td><td>Tenants, licencias, soporte, salud, catálogo de módulos, tablas comunes (fiscales, índices, geografía)</td></tr><tr><td><strong>PWA socio</strong> (<code>apps/pwa</code>, rol socio)</td><td>Socios, representantes, adherentes</td><td>AppShell <code>.pwa-mod</code>, branding del tenant</td><td><code>/api/*</code></td><td>Cuentas, facturas, pagos, consumos, reclamos, solicitudes, turnos, comunidad, perfil</td></tr><tr><td><strong>PWA empleado</strong> (misma PWA, rol empleado)</td><td>Personal</td><td>AppShell</td><td><code>/api/*</code></td><td>Bandeja de tareas, aprobaciones, comunicaciones internas, recibos de sueldo</td></tr><tr><td><strong>PWA campo</strong> (misma PWA, roles técnico/lecturista/cobrador)</td><td>Personal de campo</td><td>AppShell offline-first</td><td><code>/api/*</code></td><td>Órdenes de trabajo, lecturas, cobranza, stock en vehículo</td></tr><tr><td><strong>Landing</strong> (<code>apps/landing</code>)</td><td>Público</td><td>Layout público con marca</td><td><code>/api/public/&amp;lt;slug&gt;/*</code></td><td>Institucional, noticias, servicios, registro, consulta y pago sin login, solicitudes, baja pública (BASE §53)</td></tr><tr><td><strong>API terceros</strong></td><td>Sistemas externos</td><td>—</td><td><code>/api/v1/ext/*</code></td><td>Recursos expuestos con scopes (T10)</td></tr><tr><td><strong>Agente local</strong></td><td>Puestos con hardware</td><td>Servicio local</td><td>Canal seguro con la API</td><td>Turnero, impresoras, balanzas, lectoras (T06, M09)</td></tr></tbody></table><hr><h2 id="_9-mapa-del-sitio-resumen-mapa-completo-con-rutas-y-capabilities-en-t03" tabindex="-1">9. Mapa del sitio (resumen; mapa completo con rutas y capabilities en T03) <a class="header-anchor" href="#_9-mapa-del-sitio-resumen-mapa-completo-con-rutas-y-capabilities-en-t03" aria-label="Permalink to &quot;9. Mapa del sitio (resumen; mapa completo con rutas y capabilities en T03)&quot;">​</a></h2><h3 id="_9-1-admin-clusters-y-grupos" tabindex="-1">9.1 Admin: clusters y grupos <a class="header-anchor" href="#_9-1-admin-clusters-y-grupos" aria-label="Permalink to &quot;9.1 Admin: clusters y grupos&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Cluster</th><th>Grupos (anexo)</th></tr></thead><tbody><tr><td>Inicio</td><td>Tablero por rol, bandeja de tareas (T11), notificaciones, accesos fijados</td></tr><tr><td>Socios y cuentas</td><td>Personas, titulares, cuentas, inmuebles/domicilios, grupo familiar, documentación (M01)</td></tr><tr><td>Servicios</td><td>Catálogo, planes, categorías, conexiones/suministros, altas/bajas/cambios (M02)</td></tr><tr><td>Medición</td><td>Medidores, rutas, lecturas, validación, telemedición, prepago (M03)</td></tr><tr><td>Facturación</td><td>Tarifas y cuadros (M04), ciclos, lotes, comprobantes, distribución (M05), fiscal (M06)</td></tr><tr><td>Cobranza</td><td>Cuenta corriente, caja, entes, débitos, pasarelas, conciliación (M07)</td></tr><tr><td>Mora</td><td>Instancias, intereses, cortes/reconexiones, convenios, judicial (M08)</td></tr><tr><td>Atención</td><td>Solicitudes, reclamos, tickets, mesa de entradas, turnero, canales, bot (M09)</td></tr><tr><td>Técnica</td><td>Agenda, órdenes de trabajo, cuadrillas, redes/GIS, obras, aprovisionamiento, telefonía (M10)</td></tr><tr><td>Ventas</td><td>Presupuestos, ventas, POS (M11)</td></tr><tr><td>Administración</td><td>Compras y proveedores (M12), stock y activos (M13), tesorería (M14), contabilidad (M15)</td></tr><tr><td>Personal</td><td>Legajos, liquidaciones, portal del empleado (M16)</td></tr><tr><td>Institucional</td><td>Asociados, capital, asambleas, consejo, INAES (M17)</td></tr><tr><td>Servicios sociales</td><td>Sepelio, cementerio, salud/ambulancias, banco de sangre, vivienda, flota/traslados (M18)</td></tr><tr><td>Comunidad</td><td>Muro, novedades, encuestas, campañas, plantillas, audiencias, moderación (T09)</td></tr><tr><td>Sitio y portal</td><td>Landing, contenidos, configuración del portal (M19)</td></tr><tr><td>Reportes</td><td>Catálogo de reportes, tableros, exportaciones, BI (T10)</td></tr><tr><td>Configuración</td><td>Parámetros, tablas maestras, geografía, diccionario, marca, workflows, integraciones, usuarios y roles, auditoría (T02, T03, T04, T06, T11)</td></tr></tbody></table><h3 id="_9-2-pwa-socio-tabbar" tabindex="-1">9.2 PWA socio (tabbar) <a class="header-anchor" href="#_9-2-pwa-socio-tabbar" aria-label="Permalink to &quot;9.2 PWA socio (tabbar)&quot;">​</a></h3><p>Tabbar de cinco posiciones con botón flotante (FAB) central, según T03 §10.1.4, RF-UXD-066 y CTR-UXD-12 (mapa del sitio <code>SM-PWS-001</code>, <code>002</code>, <code>017</code> y <code>026</code> de T03 §10.8):</p><ol><li><strong>Inicio</strong> (<code>/inicio</code>): saldo, próximo vencimiento, alertas y novedades.</li><li><strong>Cuentas y servicios</strong> (<code>/servicios</code>).</li><li><strong>FAB &quot;+&quot;</strong> central: por defecto <strong>Pagar</strong> en Inicio y Facturas; su acción cambia por pantalla (<code>useCreateAction</code>): &quot;Nueva gestión&quot; en Gestiones, &quot;Contratar&quot; en Servicios, &quot;Vincular cuenta&quot; en Cuentas.</li><li><strong>Gestiones</strong> (<code>/gestiones</code>): reclamos, solicitudes y turnos.</li><li><strong>Comunidad</strong> (<code>/comunidad</code>).</li></ol><p><strong>Perfil</strong> no ocupa una posición de la tabbar: se abre desde el avatar de la topbar. El tenant puede reemplazar Comunidad (slot 4 de T03) por configuración (RF-UXD-177), sin otorgar permisos.</p><p><em>Reemplazado (corrección 05-11-2026):</em> la lista anterior enumeraba seis destinos (Inicio, Cuentas y servicios, Pagar como FAB, Gestiones, Comunidad y Perfil) para cinco posiciones; se alinea a T03, dueño del mapa del sitio (§9). La tabbar que lista M19 §10 (&quot;Inicio · Servicios · (+) · Facturas · Perfil&quot;) no coincidía con T03; <em>resuelto (cierre de residuales 05-11-2026):</em> M19 la alineó con RF-POR-180 (Inicio · Cuentas y servicios · (+) · Gestiones · Comunidad, con PAN-POR-105 <code>/app/comunidad</code>; PA-POR-20). Antes: &quot;no coincide con T03 y la debe alinear el dueño de M19&quot;. El rótulo corto de la posición 2 es &quot;Cuentas&quot; (RN-UXD-006, máximo 12 caracteres; T03 §10.1.4).</p><p>El detalle está en M19 y T03.</p><h3 id="_9-3-pwa-campo-tabbar" tabindex="-1">9.3 PWA campo (tabbar) <a class="header-anchor" href="#_9-3-pwa-campo-tabbar" aria-label="Permalink to &quot;9.3 PWA campo (tabbar)&quot;">​</a></h3><ol><li><strong>Hoy</strong>: agenda.</li><li><strong>Órdenes / Rutas / Cobranza</strong>, según el rol.</li><li><strong>Nuevo</strong> (FAB contextual).</li><li><strong>Stock en vehículo</strong>.</li><li><strong>Sincronización</strong>.</li></ol><p>El detalle está en M10, M03, M07 y T03.</p><hr><h2 id="_10-mainlayouts-detalle-en-t03" tabindex="-1">10. MainLayouts (detalle en T03) <a class="header-anchor" href="#_10-mainlayouts-detalle-en-t03" aria-label="Permalink to &quot;10. MainLayouts (detalle en T03)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layout</th><th>Estructura</th><th>Comportamiento clave</th></tr></thead><tbody><tr><td><strong>AdminShell</strong></td><td>Topbar (logo del producto, logo del tenant, selector de contexto tenant/sucursal, buscador, Mapa del sitio, accesos fijados, notificaciones, usuario) + menú lateral generado desde <code>siteMapGroups</code> + área de contenido</td><td>El menú, el mapa del sitio y el editor de roles usan la <strong>misma</strong> declaración; los ítems se filtran por capability.</td></tr><tr><td><strong>Página admin</strong></td><td><code>AdminStickyHeader</code> (título, subtítulo, acciones) + <code>ScreenHelp</code> (qué/quién/cuándo/dónde/por qué/cómo + caso de uso) + filtros + <code>DataTable</code> + modales <code>sm/md/lg/xl</code></td><td>Altas y ediciones en modal; importaciones con <code>ExcelImportWizard</code>.</td></tr><tr><td><strong>Plataforma</strong></td><td>AdminShell con contexto <code>PLATFORM</code> y estética diferenciada</td><td>Rutas <code>meta.platformOnly</code>.</td></tr><tr><td><strong>AppShell (PWA)</strong></td><td>Topbar con marca del tenant + banners (offline, avisos de corte, deuda) + contenido + tabbar con FAB &quot;+&quot; contextual</td><td>Phone shell centrado en escritorio.</td></tr><tr><td><strong>Listados PWA</strong></td><td>Cards con anatomía fija, 3 skeletons de carga, estados vacíos con acción</td><td>Alta siempre en modal desde el FAB.</td></tr><tr><td><strong>Landing</strong></td><td>Header con marca + hero + servicios habilitados + noticias + accesos (registro, pagar, reclamos) + footer institucional</td><td>Contenido administrado en M19; branding runtime.</td></tr></tbody></table><hr><h2 id="_11-design-system-marca-y-diccionario-detalle-en-t03" tabindex="-1">11. Design system, marca y diccionario (detalle en T03) <a class="header-anchor" href="#_11-design-system-marca-y-diccionario-detalle-en-t03" aria-label="Permalink to &quot;11. Design system, marca y diccionario (detalle en T03)&quot;">​</a></h2><ul><li><strong>Admin</strong>: tema oscuro por defecto con tokens CNX §4.1, tema claro opcional, tipografías Space Grotesk (títulos), IBM Plex Sans (texto) e IBM Plex Mono (importes, lecturas y códigos). Estados <code>ok/warn/bad</code>.</li><li><strong>PWA</strong>: piel <code>.pwa-mod</code> con los tokens CNX §3.1, fondo con glow, tema claro/oscuro y tipografía Sora.</li><li><strong>Marca por tenant en runtime</strong>: <ul><li><code>applyBrandingCssVars</code>;</li><li><code>applyTenantPwaIdentity</code>;</li><li>manifest dinámico y <code>theme-color</code>;</li><li>logos jerárquicos, splash e imágenes por canal.</li></ul></li><li><strong>Componentes base</strong>: <ul><li>generales: <code>DataTable</code>, <code>ExcelImportWizard</code>, Toasts, <code>ConfirmDialog</code>;</li><li>de dominio: <code>AudiencePicker</code>, <code>MoneyInput</code>/<code>MoneyDisplay</code>, <code>DateRange</code>, <code>AddressPicker</code> con mapa, <code>EntityPicker</code>, <code>StatusBadge</code>;</li><li>de soporte: <code>AuditTimeline</code>, <code>FileUploader</code> privado, <code>SignaturePad</code>, <code>OfflineBanner</code>, <code>KpiGrid</code>.</li></ul></li><li><strong>Accesibilidad</strong>: WCAG 2.2 AA (AGR-032).</li><li><strong>Diccionario</strong> (BASE §65): <ul><li>claves <code>dict:&amp;lt;clave&gt;</code> con fallback de plataforma;</li><li>variables y pluralización;</li><li>variantes por canal;</li><li>publicación versionada por tenant.</li><li>Reemplaza los textos VAR_PMOVIL de CoopOnline.</li></ul></li></ul><h3 id="_11-1-guia-operativa-para-equipos-de-desarrollo" tabindex="-1">11.1 Guía operativa para equipos de desarrollo <a class="header-anchor" href="#_11-1-guia-operativa-para-equipos-de-desarrollo" aria-label="Permalink to &quot;11.1 Guía operativa para equipos de desarrollo&quot;">​</a></h3><p>Para implementar <strong>cualquier</strong> pantalla o flujo sin reinterpretar T03 en cada módulo, usar el apartado exclusivo <strong><a href="./GUIA-UI-UX-DESARROLLO"><code>GUIA-UI-UX-DESARROLLO.md</code></a></strong>:</p><ul><li>jerarquía documental (esta guía → T03 → anexo del módulo);</li><li>shells obligatorios por app;</li><li>checklist por <code>PAN-*</code>;</li><li>reglas no negociables, catálogo de componentes, accesibilidad, anti‑patrones;</li><li>ayuda (<code>ScreenHelp</code> vs FAQ de portal/bot);</li><li>stack React (DEC-113) sin alterar las reglas de experiencia.</li></ul><p>T03 sigue siendo la fuente normativa de tokens, RF-UXD-* y mapa del sitio; la guía condensa lo que todo PR de front debe cumplir.</p><h3 id="_11-2-identidad-visual-del-producto-dec-119" tabindex="-1">11.2 Identidad visual del producto (DEC-119) <a class="header-anchor" href="#_11-2-identidad-visual-del-producto-dec-119" aria-label="Permalink to &quot;11.2 Identidad visual del producto (DEC-119)&quot;">​</a></h3><p>Naming (DEC-109), paleta, logotipos del <strong>producto</strong> CoopApps, checklist de entrega y semilla del tenant <code>PLATFORM</code>: <strong><a href="./08-identidad-marca-coopapps"><code>08-identidad-marca-coopapps.md</code></a></strong> y archivos en <strong><code>docs/brand/coopapps/</code></strong>. No confundir con la marca editable de cada cooperativa (<code>tenantBrandings</code>, T03 §7.B.1).</p><hr><h2 id="_12-indice-de-modulos-y-duenos-de-datos" tabindex="-1">12. Índice de módulos y dueños de datos <a class="header-anchor" href="#_12-indice-de-modulos-y-duenos-de-datos" aria-label="Permalink to &quot;12. Índice de módulos y dueños de datos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Anexo</th><th>Código</th><th>Nombre</th><th>Dueño de (entidades principales)</th><th>Olas</th></tr></thead><tbody><tr><td>T01</td><td>PLA</td><td>Plataforma SaaS</td><td>tenants, licencias, contratos SaaS, moduleCatalog, ambientes, accesos de soporte; infraestructura de eventos <code>outboxEvents</code>, <code>inboxReceipts</code>, <code>jobRuns</code> (T05 COL-PLA-24)</td><td>O0–O1</td></tr><tr><td>T02</td><td>IAM</td><td>Identidad, roles, auditoría</td><td>identities, memberships (el usuario del personal es <code>memberships.staff</code>; no existe colección <code>users</code>), roles, perfiles, sesiones, auditLogs (cambios) + auditAccess, auditReads, auditMessages, auditAi (CTR-IAM-16)</td><td>O0–O1</td></tr><tr><td>T03</td><td>UXD</td><td>UX, marca, diccionario</td><td>branding, dictionaryEntries, siteMap</td><td>O0–O1</td></tr><tr><td>T04</td><td>CFG</td><td>Configuración y maestros</td><td>configVersions, parameters, legalEntities (personas jurídicas del tenant, DEC-064; <code>legalEntityId</code> en documentos económicos desde O0), tablas maestras, geografía, calles, calendarios, índices</td><td>O0–O1</td></tr><tr><td>T05</td><td>DAT</td><td>Modelo de datos canónico</td><td>(no es dueño y no tiene colecciones nuevas propias: consolida 1.108 filas de colecciones de los demás anexos (antes 1.104), de las que se crean 1.057 (antes 1.053; 39 en la base analítica <code>bi_*</code>); en el cierre de la corrección de inconsistencias, 05-11-2026 se suman <code>costCenterModels</code> (M15), <code>bundleSubscriptions</code> (M02), <code>fiscalClasses</code> (M06) y <code>collectionAccountingGroups</code> (M07), con dueño, clasificación, índices y ola; nombres canónicos y contraposiciones CTR-DAT; prevalece sobre los nombres de esta tabla)</td><td>O0 (convenciones)</td></tr><tr><td>T06</td><td>INT</td><td>Integraciones</td><td>connectors, connectorConfigs, integrationSecrets (bóveda, DEC-074; antes citada como <code>vaultSecrets</code>), integrationLogs, webhooks</td><td>O0–O11</td></tr><tr><td>T07</td><td>MIG</td><td>Migración ProCoop</td><td>migrationRuns, mappings, legacyIds</td><td>O1, O11</td></tr><tr><td>T08</td><td>NFR</td><td>No funcionales y seguridad</td><td>(requisitos; consentimientos y retención compartidos con T09/T02)</td><td>O0+</td></tr><tr><td>T09</td><td>COM</td><td>Comunidad y comunicaciones</td><td>posts, comments, reactions, news, surveys, audiences, templates, campaigns, notifications, preferences</td><td>O2+</td></tr><tr><td>T10</td><td>BIA</td><td>Reportes, BI, APIs</td><td>reportDefinitions, reportRuns, dashboards, apiClients</td><td>O1–O11</td></tr><tr><td>T11</td><td>WFL</td><td>Workflow, eventos, documentos</td><td>catálogo de eventos <code>eventTypes</code> (668 IDs EVT, antes 658, T11 §12.10; con alias) y de jobs (506 IDs JOB); workflows, tasks, approvals, documents, documentTemplates, perfiles de firma (DEC-078). La colección <code>outboxEvents</code> la provee T01</td><td>O0–O2</td></tr><tr><td>T12</td><td>SRV</td><td>Fichas verticales por servicio (DEC-073), en dos partes: <code>T12-SRV-fichas-verticales-servicios-parte1.md</code> (INT, TEL, TV, ELE, AG, CLO, GAS, ALU) y <code>-parte2.md</code> (OBR, SEP, CEM, SAN, SAL, VIV, TAS, CAP, OTR)</td><td>(no es dueño; recorre cada servicio de punta a punta referenciando M02–M19; sus huecos van a <code>05-registro-huecos.md</code>)</td><td>—</td></tr><tr><td>M01</td><td>PER</td><td>Personas, titulares, cuentas</td><td>persons, accounts, properties, addresses, relationships</td><td>O2</td></tr><tr><td>M02</td><td>CAT</td><td>Catálogo de servicios</td><td>services, products, plans, categories, serviceContracts/connections</td><td>O2</td></tr><tr><td>M03</td><td>MED</td><td>Medición y consumos</td><td>meters, routes, readings, consumptions</td><td>O7</td></tr><tr><td>M04</td><td>TAR</td><td>Tarifas y motor de cálculo</td><td>tariffs, tariffVersions, concepts, formulas</td><td>O4, O7</td></tr><tr><td>M05</td><td>FAC</td><td>Facturación</td><td>billingCycles, billingBatches, invoices, invoiceLines</td><td>O4</td></tr><tr><td>M06</td><td>FIS</td><td>Fiscal e impuestos</td><td>taxRules, taxPadrons, fiscalPoints, caeRequests, regimes</td><td>O4, O8</td></tr><tr><td>M07</td><td>COB</td><td>Cuenta corriente y cobranza</td><td>ledgerEntries, payments, receipts, cashboxes, collectionAgents, debits</td><td>O5</td></tr><tr><td>M08</td><td>MOR</td><td>Mora y financiación</td><td>arrearsCases, interestRuns, cutoffOrders, agreements, guarantees</td><td>O6</td></tr><tr><td>M09</td><td>CRM</td><td>CRM y atención</td><td>requests, claims, tickets, intake, queues/turns, channels</td><td>O2–O3, O6 (IA y omnicanal, DEC-056), O10</td></tr><tr><td>M10</td><td>TEC</td><td>Técnica y campo</td><td>workOrders, crews, schedules, networkAssets, provisioning, telephony</td><td>O3, O10</td></tr><tr><td>M11</td><td>VEN</td><td>Ventas y POS</td><td>quotes, sales, posSessions</td><td>O4–O8</td></tr><tr><td>M12</td><td>CMP</td><td>Compras y proveedores</td><td>suppliers, purchaseRequests, purchaseOrders, supplierInvoices (incluye la factura del mayorista de energía y gas), liquidación de derechos de señales</td><td>O3 (dos RF de soporte), O8</td></tr><tr><td>M13</td><td>STK</td><td>Stock, activos, fabricación</td><td>items, warehouses, stockMoves, serials, fixedAssets, productionOrders</td><td>O3 (serializado), O8, O10</td></tr><tr><td>M14</td><td>TES</td><td>Tesorería y bancos</td><td>bankAccounts, treasuryMoves, checks/valores, reconciliations</td><td>O5, O8 (DEC-059)</td></tr><tr><td>M15</td><td>CON</td><td>Contabilidad</td><td>chartOfAccounts, fiscalYears, costCenters, journalEntries, postingRules</td><td>O5 (núcleo), O8</td></tr><tr><td>M16</td><td>SUE</td><td>Personal y sueldos</td><td>employees, payrollConcepts, payrollRuns, payslips</td><td>O3 (legajo mínimo), O8 (importación externa), O9 (DEC-058)</td></tr><tr><td>M17</td><td>INS</td><td>Institucional</td><td>members (asociados), capitalMovements y capitalBalances, assemblies, boardMinutes</td><td>O5 (capital mínimo, DEC-019), O10</td></tr><tr><td>M18</td><td>SOC</td><td>Servicios sociales y flota</td><td>socialPlans, adherentes y beneficiarios (<code>serviceDependents</code>, <code>serviceBeneficiaries</code>, dueño único, DEC-071/DEC-086), housingPlans y housingPrices, transportTrips, burialRights, contractRegistrations, vehicles</td><td>O4 (adherentes y billing-inputs, DEC-071), O10</td></tr><tr><td>M19</td><td>POR</td><td>Landing y portal del socio</td><td>sitePages, portalConfig, selfServiceSessions</td><td>O2+</td></tr></tbody></table><p>El modelo de datos completo y la asignación de cada colección a su dueño se consolida en <code>anexos/T05-DAT-modelo-datos.md</code>. Esta tabla resume las entidades principales; ante cualquier diferencia de nombre o de dueño, prevalece el catálogo de T05 (§7) con sus contraposiciones CTR-DAT (§20).</p><hr><h2 id="_13-convenciones-transversales-de-desarrollo" tabindex="-1">13. Convenciones transversales de desarrollo <a class="header-anchor" href="#_13-convenciones-transversales-de-desarrollo" aria-label="Permalink to &quot;13. Convenciones transversales de desarrollo&quot;">​</a></h2><p>Son obligatorias para todo código generado. Detalle en <code>_GUIA-REDACCION-ANEXOS.md</code> §5.</p><table tabindex="0"><thead><tr><th>Tema</th><th>Convención</th></tr></thead><tbody><tr><td>Idioma</td><td>Código, colecciones, campos y endpoints en inglés camelCase; UI en español vía <code>dict:&amp;lt;clave&gt;</code></td></tr><tr><td>Documento base</td><td><code>tenantId</code>, <code>createdAt</code>, <code>updatedAt</code>, <code>createdBy</code>, <code>updatedBy</code>, <code>version</code>; según el caso <code>status</code>, <code>validFrom</code>/<code>validTo</code>, <code>recordedAt</code> y <code>deletedAt</code> (nunca en documentos económicos)</td></tr><tr><td>Dinero</td><td><code>Decimal128</code> + <code>decimal.js</code>; precisión y redondeo por concepto (AGR-011); <code>currency</code> (ARS por defecto)</td></tr><tr><td>Fechas</td><td>UTC almacenado; zona del tenant (<code>America/Argentina/Cordoba</code> por defecto); visible <code>dd-mm-yyyy</code></td></tr><tr><td>Capabilities</td><td><code>modulo.recurso.accion</code> + alcance</td></tr><tr><td>API</td><td><code>/api</code>, <code>/api/admin</code>, <code>/api/platform</code>, <code>/api/public/&amp;lt;tenantSlug&gt;</code>, <code>/api/v1/ext</code>; paginación <code>{items,total,page,size}</code>; errores RFC 9457 con <code>requestId</code>; <code>Idempotency-Key</code></td></tr><tr><td>Eventos</td><td><code>&amp;lt;mod&gt;.&amp;lt;entidad&gt;.&amp;lt;pasado&gt;</code> vía outbox</td></tr><tr><td>Jobs</td><td><code>&amp;lt;mod&gt;:&amp;lt;proceso&gt;</code>, idempotentes, reanudables, con progreso</td></tr><tr><td>IDs de documentación</td><td>RF-, RN-, RNF-, CU-, PAN-, API-, EVT-, JOB-, PRM-, PA-, CTR- + <code>&amp;lt;COD&gt;-NNN</code></td></tr><tr><td>Prioridad / estado</td><td>Núcleo / Estándar / Extensión · Informado / Adoptado / A validar / Reemplazado por / Descartado</td></tr><tr><td>Pruebas</td><td>Toda funcionalidad con pruebas de permisos negativos y de aislamiento de tenant</td></tr></tbody></table><hr><h2 id="_14-requisitos-no-funcionales-resumen-detalle-medible-en-t08" tabindex="-1">14. Requisitos no funcionales (resumen; detalle medible en T08) <a class="header-anchor" href="#_14-requisitos-no-funcionales-resumen-detalle-medible-en-t08" aria-label="Permalink to &quot;14. Requisitos no funcionales (resumen; detalle medible en T08)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Área</th><th>Meta resumida</th></tr></thead><tbody><tr><td>Seguridad</td><td>OWASP ASVS nivel 2; 2FA para el personal; bóveda de secretos; cifrado en tránsito y en reposo; rate limiting; uploads seguros; sin secretos en el código</td></tr><tr><td>Aislamiento</td><td>Pruebas automáticas de aislamiento multitenant en CI que bloquean el merge</td></tr><tr><td>Privacidad</td><td>Ley 25.326: consentimientos, finalidad, derechos de acceso/rectificación/supresión, retención y anonimización</td></tr><tr><td>Rendimiento</td><td>Pantallas interactivas p95 ≤ 800 ms (DEC-063); facturación masiva por job con progreso y reanudación (50.000 suministros ≤ 60 min, T08 PA-NFR-04)</td></tr><tr><td>Capacidad</td><td>Tenant estándar 25.000 suministros y grande 150.000; diseño para 100 tenants y hasta 300 sin rediseño (DEC-075)</td></tr><tr><td>Disponibilidad</td><td>99,5 % mensual comprometido; RPO ≤ 15 min; RTO ≤ 4 h por tenant y ≤ 8 h plataforma completa; soporte lunes a viernes 8–18 con P1 24×7 (DEC-063)</td></tr><tr><td>Alojamiento</td><td><strong>Microsoft Azure</strong> (DEC-112); cláusulas de transferencia según la AAIP (DEC-062); GoodApps es prestador de tratamiento, art. 25 Ley 25.326 (DEC-076)</td></tr><tr><td>Secretos</td><td>Bóveda con cifrado por sobre y clave maestra en <strong>Azure Key Vault</strong> (DEC-074)</td></tr><tr><td>Observabilidad</td><td>Logs estructurados con tenant/request, métricas, trazas y alertas de jobs e integraciones</td></tr><tr><td>Exactitud</td><td>Cero diferencias de centavos entre comprobante, cuenta corriente y contabilidad</td></tr><tr><td>Offline</td><td>PWA de campo operativa sin conexión, con cola idempotente</td></tr><tr><td>Accesibilidad</td><td>WCAG 2.2 AA</td></tr></tbody></table><hr><h2 id="_15-plan-de-olas-resumen-de-contenido-detalle-en-03-plan-de-olas-y-prompts-md-build-03-norma-ejecucion-goodapps-md-dec-118" tabindex="-1">15. Plan de olas (resumen de <strong>contenido</strong>; detalle en <code>03-plan-de-olas-y-prompts.md</code>; build: <code>03-norma-ejecucion-goodapps.md</code>, DEC-118) <a class="header-anchor" href="#_15-plan-de-olas-resumen-de-contenido-detalle-en-03-plan-de-olas-y-prompts-md-build-03-norma-ejecucion-goodapps-md-dec-118" aria-label="Permalink to &quot;15. Plan de olas (resumen de **contenido**; detalle en \`03-plan-de-olas-y-prompts.md\`; build: \`03-norma-ejecucion-goodapps.md\`, DEC-118)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ola</th><th>Contenido</th><th>Hito de salida</th></tr></thead><tbody><tr><td>O0</td><td>Fundaciones: solución .NET+React, Docker/CI, librerías compartidas, shells, design system, auth básica, tenancy, auditoría, outbox/colas Azure, almacenamiento Blob, diccionario/branding base, notificaciones base, entidades jurídicas del tenant y sucursales (<code>legalEntities</code> y <code>branches</code>, REQ-DEC-064 cubierto por RF-CFG-134..138 y 140; <code>legalEntityId</code> obligatorio por RF-CFG-136; <code>workstations</code> en O1 y perfil fiscal <code>fiscalProfiles</code> de M06 en O4)</td><td>Un tenant de demo con login, menú vacío y pruebas de aislamiento verdes</td></tr><tr><td>O1</td><td>Plataforma e IAM completos, configuración versionada, parámetros, maestros, geografía, workflow de autorizaciones, expediente documental</td><td>Alta asistida de una cooperativa con usuarios, roles y configuración publicada</td></tr><tr><td>O2</td><td>Personas/cuentas, catálogo de servicios, landing, registro y portal base, CRM de solicitudes, comunidad</td><td>Un socio se registra y solicita Internet desde la landing</td></tr><tr><td>O3</td><td>Técnica para Internet: factibilidad, agenda, OT, instalación, comodato, stock serializado, app de campo offline, aprovisionamiento; legajo mínimo de personal (DEC-058)</td><td>El servicio queda instalado y activo</td></tr><tr><td>O4</td><td>Motor tarifario, facturación, ARCA, impuestos básicos; adherentes y sus entradas a facturar (DEC-071)</td><td>Primera factura electrónica con CAE</td></tr><tr><td>O5</td><td>Cuenta corriente, caja, pasarelas prioritarias (DEC-015), débitos, conciliación, tesorería operativa (DEC-059), núcleo contable (DEC-009) y capital social mínimo (DEC-019)</td><td>Pago online imputado y asentado</td></tr><tr><td>O6</td><td>Mora, suspensión/corte/reconexión, convenios, incobrables; IA y omnicanal de atención (DEC-056)</td><td><strong>Piloto Internet completo de punta a punta</strong></td></tr><tr><td>O7</td><td>Servicios medidos (electricidad, agua, cloacas, gas, alumbrado), lecturas, telemedición, tarifas medidas, reguladores, obras y contribución por mejoras; migración comercial vigente, paralelo, by-pass y corte comercial por servicio (DEC-089)</td><td>Facturación de energía con lecturas; corte comercial de electricidad, gas y prepago de la piloto al cerrar la ola (DEC-089)</td></tr><tr><td>O8</td><td>ERP administrativo: compras, stock completo, tesorería, contabilidad completa, regímenes informativos; importación de sueldos externos (DEC-058)</td><td>Cierre contable mensual</td></tr><tr><td>O9</td><td>Personal y sueldos</td><td>Liquidación mensual con F.931/LSD</td></tr><tr><td>O10</td><td>Institucional, servicios sociales, flota, telefonía, TV, fabricación, turnero, actividades</td><td>Asamblea y servicios sociales operativos</td></tr><tr><td>O11</td><td>BI, generador de reportes, APIs de terceros, pasarelas restantes, migración repetible e históricos (DEC-089; antes también &quot;paralelo y by-pass&quot;, que pasan a O7)</td><td>Corte administrativo y apagado de ProCoop en una cooperativa (DEC-068, DEC-089; antes &quot;Corte de ProCoop por etapas en una cooperativa: primero comercial y luego administrativo&quot;)</td></tr></tbody></table><p>El plan detallado (versión 1.2 del 10-11-2026; recuento 19-11-2026) tiene <strong>174</strong> prompts <code>PRO-O*</code> (más <strong>4</strong> <code>PRO-GEN</code> en <code>03-norma</code>, incluido <strong>PRO-GEN-04</strong> control pre-PR) que cubren los <strong>4.213</strong> RF (antes 4.204, versión 1.2: se suman 9 RF de DEC-093 a DEC-108; antes 4.203; se suma RF-POR-180 de M19, Comunidad en la tabbar del socio, en O2, cierre de la corrección de inconsistencias, 05-11-2026) y los 293 RNF de los anexos (antes 292; se suma RNF-NFR-260, DEC-100), cada uno asignado a exactamente un prompt (recontado por script leyendo los anexos; §18 y §19 del plan documentan las reasignaciones y las 16 contradicciones de ola, y §21 y §22 los cambios de las versiones 1.1 y 1.2). Reparto de RF por ola: O0 305, O1 459 (antes 458), O2 617 (antes 614 y 613), O3 319, O4 425 (antes 424), O5 470 (antes 469), O6 244, O7 298 (DEC-089; antes 274), O8 465 (antes 462), O9 163, O10 383, O11 65 (DEC-089; antes 89). Reparto de prompts por ola: O0 21, O1 20, O2 19, O3 13, O4 16, O5 14, O6 11, O7 12 (DEC-089: se suman PRO-O7-11 y PRO-O7-12; antes 10), O8 15, O9 9, O10 14, O11 8 (DEC-089: PRO-O11-07 y PRO-O11-08 quedan reemplazados; antes 10). RNF por ola: O0 144, O1 73 (antes 72), O2 15, O3 9, O4 23, O5 13, O6 2, O7 1 (DEC-089: RNF-NFR-154; antes 0), O8 1, O9 0, O10 6, O11 6 (antes 7). Los 83 RF agregados al resolver los huecos de cobertura (<code>05-registro-huecos.md</code>) se asignaron a la ola indicada en el propio RF, sin prompts nuevos; DEC-082 a DEC-087 están reflejadas en los prompts que corresponden, y DEC-093 a DEC-107 en los prompts que cambian (plan §22; DEC-108 no afecta al plan). <em>Reemplazado (versión 1.0 del plan): 4.120 RF, con O0 299, O1 457, O2 607, O3 315, O4 419, O5 463, O6 241, O7 256, O8 454, O9 161, O10 360, O11 88.</em> <em>Reemplazado (corrección 05-11-2026 del plan, §21.5): O5 468 y O11 90; RF-CON-160 empieza en O5 (saldos de apertura) y su migración completa queda como extensión en O11. El total (4.203 RF y 292 RNF) y los prompts por ola no cambian.</em></p><hr><h2 id="_16-como-usar-esta-especificacion-con-goodapps" tabindex="-1">16. Cómo usar esta especificación con GoodApps <a class="header-anchor" href="#_16-como-usar-esta-especificacion-con-goodapps" aria-label="Permalink to &quot;16. Cómo usar esta especificación con GoodApps&quot;">​</a></h2><ol><li><strong>Archivo maestro</strong>: GACAC (<code>docs/especificacion/</code>) conserva alcance, RF/RN, pantallas, casos de prueba y trazabilidad.</li><li><strong>Export</strong>: por módulo en Markdown al repo GoodApps (<code>coodo</code>), con PR y sin PII; pipeline y agentes según acuerdo GoodApps (DEC-118).</li><li><strong>Unidad de trabajo</strong>: un módulo o bloque transversal (p. ej. M01 + T02) con su anexo, casos de uso, OpenAPI de diseño y matriz de ayuda (§6.1–6.2 de <code>06</code>).</li><li><strong>Stack</strong>: implementación según §5 de este documento y <code>07-modelo-relacional-azure-sql.md</code>; el <strong>funcional</strong> no se reinterpreta sin nueva DEC.</li><li><strong>Definición de terminado</strong> (diseño): criterios de aceptación del anexo; trazabilidad RF/RN; inventario ScreenHelp/FAQ donde aplique; decisión cerrada en <code>01</code> si hubo cambio de comportamiento.</li><li><strong>Preguntas abiertas</strong>: registrar en <code>02-preguntas-abiertas.md</code>; hasta cerrar, rige la opción recomendada.</li><li><strong>Checklist de alineación documental</strong>: <code>06-impacto-adaptacion-stack-goodapps.md</code> §12.</li><li><strong>Listo para construcción (export / arranque O0)</strong>: semáforo y límites en <code>13-coherencia-especificacion.md</code> §8 (19-11-2026).</li></ol><hr><h2 id="_17-registro-global-de-contraposiciones-resueltas" tabindex="-1">17. Registro global de contraposiciones resueltas <a class="header-anchor" href="#_17-registro-global-de-contraposiciones-resueltas" aria-label="Permalink to &quot;17. Registro global de contraposiciones resueltas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>CTR</th><th>Fuentes en conflicto</th><th>Conflicto</th><th>Resolución</th><th>Prevalencia</th></tr></thead><tbody><tr><td>CTR-GLB-01</td><td>DFA vs CNX vs BASE §58</td><td>Stack tecnológico</td><td>.NET 10, Azure SQL, React (DEC-111, DEC-112, DEC-113)</td><td>DEC</td></tr><tr><td>CTR-GLB-02</td><td>ProCoop/DFA (una base por cooperativa) vs BASE §2 multitenant</td><td>Modelo de tenancy</td><td>Base única con <code>tenantId</code> (DEC-002)</td><td>DEC</td></tr><tr><td>CTR-GLB-03</td><td>DFA (etapas con fechas) vs pedido de olas</td><td>Planificación</td><td>Olas sin fechas (DEC-006)</td><td>DEC</td></tr><tr><td>CTR-GLB-04</td><td>DFA (Sueldos prioridad C) vs BASE §104</td><td>Alcance de sueldos</td><td>En alcance completo SUE-001..014 (O9)</td><td>BASE (§104 prevalece)</td></tr><tr><td>CTR-GLB-05</td><td>BASE (frases tempranas que excluían factura multiservicio) vs BASE §103</td><td>Factura multiservicio</td><td>Ambos modos: agrupada multiservicio y separada (FAC-005..012)</td><td>BASE más reciente</td></tr><tr><td>CTR-GLB-06</td><td>DFA (contabilidad tardía) vs integridad económica</td><td>Momento de la contabilidad</td><td>Núcleo temprano en O5, completa en O8 (DEC-009)</td><td>DEC</td></tr><tr><td>CTR-GLB-07</td><td>Supuestos iniciales (piloto energía) vs decisión</td><td>Piloto</td><td>Internet (DEC-005)</td><td>DEC</td></tr><tr><td>CTR-GLB-08</td><td>DFA prioridades B/C (módulos marginales) vs DEC-007</td><td>Alcance de módulos marginales</td><td>Todos en alcance, en olas tardías</td><td>DEC</td></tr><tr><td>CTR-GLB-09</td><td>CNX (muro abierto a publicaciones de usuarios) vs necesidad institucional</td><td>Modelo del muro</td><td>Editorial con comentarios moderados (DEC-008)</td><td>DEC</td></tr><tr><td>CTR-GLB-10</td><td>ProCoop (VARIABLE clave/valor numérica) vs BASE §81/AGR-009</td><td>Parametrización</td><td>Parámetros tipados, semánticos y versionados (T04, T04b)</td><td>BASE/AGR</td></tr><tr><td>CTR-GLB-11</td><td>ProCoop (CoopOnline con MySQL sincronizada) vs plataforma única</td><td>Portal del socio</td><td>Portal nativo sobre la misma base (M19)</td><td>BASE</td></tr><tr><td>CTR-GLB-12</td><td>ProCoop (contraseñas reversibles, usuario SQL compartido, secretos en código)</td><td>Seguridad</td><td>Hash fuerte, identidad por usuario, bóveda (T02, T06, T08)</td><td>Deuda técnica: reemplazada</td></tr></tbody></table><p>Las contraposiciones de cada módulo están en la sección 20 de su anexo.</p><hr><h2 id="_18-preguntas-abiertas" tabindex="-1">18. Preguntas abiertas <a class="header-anchor" href="#_18-preguntas-abiertas" aria-label="Permalink to &quot;18. Preguntas abiertas&quot;">​</a></h2><p>Las preguntas se consolidan en <code>02-preguntas-abiertas.md</code>, agrupadas por anexo y por ola bloqueada, con opciones y respuesta recomendada. Se presentan al solicitante en tandas interactivas. Mientras no se responden, rige la opción recomendada y los requisitos afectados quedan <code>A validar</code>.</p><p>Estado al 04-11-2026: cuestionario <strong>cerrado</strong> con 516 preguntas (las §21 de todos los anexos, T05 y los huecos de decisión de <code>05-registro-huecos.md</code>); 93 respondidas por el solicitante (DEC-011 a DEC-084) y 423 asumidas con la opción recomendada (DEC-072, DEC-087). Las preguntas que surjan de aquí en adelante se agregan al final de la tabla con el mismo criterio (DEC-047). Actualización por el cierre de la corrección de inconsistencias, 05-11-2026: 555 preguntas (antes 516), 98 respondidas (antes 93), 456 asumidas (antes 423) y 1 reemplazada; se agregan las 38 PA que los anexos registraron durante la corrección y pasan a respondidas PA-IAM-12, PA-CFG-02, PA-CFG-04, PA-MOR-20 y PA-POR-04, cuyos anexos ya aplican la DEC correspondiente. Actualización por la ronda de residuales (05-11-2026): 585 preguntas (antes 555), 98 respondidas (sin cambios), 486 asumidas (antes 456) y 1 reemplazada; se agregan las 30 PA de cierre de residuales de los anexos. Actualización por la sincronización posterior (05-11-2026): 589 preguntas (antes 585), 490 asumidas (antes 486); se agregan PA-IAM-19, PA-UXD-19, PA-DAT-05 y PA-WFL-24. Actualización del 10-11-2026: 593 preguntas (antes 589); se agregan PA-FIS-23 a PA-FIS-26 (de DEC-093, DEC-094, DEC-095 y DEC-102), en estado <code>Pendiente (contador)</code>: el sistema implementa la opción recomendada detrás de un parámetro y no precarga normas hasta la respuesta del contador.</p><p>Huecos de cobertura: <code>05-registro-huecos.md</code> registra 77 huecos detectados por las fichas verticales de T12 (27 de gravedad alta, 38 media, 12 baja; 31 de coherencia, 40 faltantes, 6 de decisión). Los de coherencia y faltantes se corrigen en el anexo responsable; los de decisión pasan a PA.</p><hr><h2 id="_19-trazabilidad-global-de-fuentes" tabindex="-1">19. Trazabilidad global de fuentes <a class="header-anchor" href="#_19-trazabilidad-global-de-fuentes" aria-label="Permalink to &quot;19. Trazabilidad global de fuentes&quot;">​</a></h2><p>La matriz completa está en <code>04-matriz-trazabilidad.md</code>. Cubre:</p><ul><li>BASE §1–§107 completo;</li><li>AGR-001..036 y ESC-01..05;</li><li>CNX por sección;</li><li>DFA módulos 1–29;</li><li>FIC 1–23;</li><li>RN-01..13 por sección;</li><li>CAT: las 659 tablas, vía T07;</li><li>los 1.536 parámetros V2, vía T04b partes 1–4;</li><li>el menú completo de ProCoop, vía T03.</li></ul><p>Para cada elemento se indica en qué anexo e ID quedó, o el motivo de <code>Descartado</code>/<code>Reemplazado</code>.</p><p>Resultado de la matriz 1.1 (05-11-2026; antes, matriz 1.0: 97,9 %, 1.659 directas y 20 débiles): 2.201 unidades de fuente, 98,0 % con destino (1.661 citadas directamente y 402 por su sección padre), 94 descartadas o reemplazadas, 18 con trazabilidad débil y 26 brechas, cada una con su corrección propuesta en la matriz (§4). Las 659 tablas de ProCoop están resueltas en T07. La matriz se regenera con el procedimiento de su §14 después de cada cambio importante de anexos.</p><hr><h2 id="_20-glosario-general" tabindex="-1">20. Glosario general <a class="header-anchor" href="#_20-glosario-general" aria-label="Permalink to &quot;20. Glosario general&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Término</th><th>Definición</th><th>Clave de diccionario</th><th>Equivalente ProCoop</th></tr></thead><tbody><tr><td>CoopApps</td><td>Marca comercial del producto SaaS (esta especificación). Todo texto visible al usuario del producto usa esta denominación salvo personalización del tenant</td><td><code>dict:product.name</code> (CoopApps)</td><td>—</td></tr><tr><td>GoodApps</td><td>Empresa desarrolladora y operadora de la plataforma; contratos SaaS, equipo de consola de plataforma y responsable legal como encargado del tratamiento de datos (DEC-076, DEC-109)</td><td><code>dict:vendor.name</code> (GoodApps)</td><td>—</td></tr><tr><td>Tenant</td><td>Cooperativa cliente de la plataforma</td><td><code>dict:tenant</code></td><td>Empresa / base de datos</td></tr><tr><td>Persona</td><td>Individuo o entidad con identidad fiscal (DNI/CUIT)</td><td><code>dict:persona</code></td><td>PERSONAS</td></tr><tr><td>Titular</td><td>Persona responsable de una cuenta</td><td><code>dict:titular</code></td><td>TITULARES</td></tr><tr><td>Asociado / Socio</td><td>Persona con vínculo institucional (capital, voto)</td><td><code>dict:socio</code></td><td>ASOCIADOS</td></tr><tr><td>Cuenta</td><td>Unidad de facturación y cuenta corriente de un titular</td><td><code>dict:cuenta</code></td><td>CUENTAS / suministro</td></tr><tr><td>Conexión / Suministro</td><td>Instancia de un servicio en un inmueble para una cuenta</td><td><code>dict:suministro</code></td><td>SUMINISTROS / SERVICIOS_CUENTA</td></tr><tr><td>Ciclo de facturación</td><td>Período y cronograma de emisión</td><td><code>dict:ciclo</code></td><td>PERIODOS / LOTES</td></tr><tr><td>Lote</td><td>Ejecución de facturación masiva sobre un universo</td><td><code>dict:lote</code></td><td>LOTES</td></tr><tr><td>Concepto</td><td>Ítem facturable (cargo fijo, consumo, impuesto, tasa)</td><td><code>dict:concepto</code></td><td>CONCEPTOS</td></tr><tr><td>Ente recaudador</td><td>Tercero que cobra por cuenta de la cooperativa</td><td><code>dict:enteRecaudador</code></td><td>ENTES</td></tr><tr><td>Capability</td><td>Permiso atómico <code>modulo.recurso.accion</code></td><td>—</td><td>Permiso por formulario</td></tr><tr><td>Ola</td><td>Incremento de desarrollo ordenado sin fecha</td><td>—</td><td>Etapa</td></tr></tbody></table><p>El glosario de cada módulo está en la sección 3 de su anexo.</p><p><strong>Nota sobre numeraciones.</strong> &quot;DFA M14&quot;, &quot;DFA M18&quot; y similares citan la numeración de los 29 módulos de ProCoop en la DFA (sección 4.3), que <strong>no</strong> coincide con los anexos <code>M01..M19</code> de esta especificación. Un código de anexo siempre va acompañado de su sigla (<code>M14 TES</code>, <code>T11 WFL</code>).</p><hr><h2 id="anexo-de-documentos-de-la-especificacion" tabindex="-1">Anexo de documentos de la especificación <a class="header-anchor" href="#anexo-de-documentos-de-la-especificacion" aria-label="Permalink to &quot;Anexo de documentos de la especificación&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Documento</th><th>Contenido</th></tr></thead><tbody><tr><td><code>00-ESPECIFICACION-MAESTRA.md</code></td><td>Este documento</td></tr><tr><td><code>01-registro-decisiones.md</code></td><td>DEC-001..010 y siguientes, con fecha y fundamento</td></tr><tr><td><code>02-preguntas-abiertas.md</code></td><td>Preguntas consolidadas con opciones y recomendación</td></tr><tr><td><code>03-plan-de-olas-y-prompts.md</code> + <code>03-norma-ejecucion-goodapps.md</code></td><td>Olas O0–O11, 174 PRO-O + 4 PRO-GEN; mapa RF vs stack GoodApps</td></tr><tr><td><code>04-matriz-trazabilidad.md</code></td><td>Fuente → anexo/ID</td></tr><tr><td><code>05-registro-huecos.md</code></td><td>Huecos de cobertura y contradicciones entre anexos detectados por las fichas verticales (T12), con propuesta y estado</td></tr><tr><td><code>_GUIA-REDACCION-ANEXOS.md</code></td><td>Convenciones y plantilla</td></tr><tr><td><code>../revision-externa/NucleoTransversal-contraste.md</code> y <code>NucleoTransversal-rechazados.md</code></td><td>Contraste del documento externo <code>NucleoTransversal-Modelo</code>; no es fuente (§2.3)</td></tr><tr><td><code>anexos/T01..T11</code>, <code>T04b</code> partes 1–4</td><td>Anexos transversales</td></tr><tr><td><code>anexos/M01..M19</code></td><td>Anexos de módulo</td></tr></tbody></table>`,143)])])}const g=e(r,[["render",n]]);export{m as __pageData,g as default};
